AK.QUESTIONS = [
  // ================= 野菜 =================
  { id: 'v01', f: 'veg', q: 'トマトは何科の野菜？', c: ['ナス科', 'ウリ科', 'アブラナ科', 'ヒルガオ科'], e: 'トマトはナス科。ナス・ピーマン・トウガラシ・ジャガイモも同じナス科で、連作障害に注意が必要。' },
  { id: 'v02', f: 'veg', q: 'キュウリは何科の野菜？', c: ['ウリ科', 'ナス科', 'マメ科', 'アオイ科'], e: 'ウリ科にはカボチャ・スイカ・メロン・ニガウリなどがある。巻きひげを伸ばすつる性のものが多い。' },
  { id: 'v03', f: 'veg', q: 'ダイコンは何科の野菜？', c: ['アブラナ科', 'セリ科', 'キク科', 'ヒユ科'], e: 'アブラナ科にはキャベツ・ハクサイ・ブロッコリー・カブなどがある。4枚の花弁が十字形に並ぶのが特徴。' },
  { id: 'v04', f: 'veg', q: 'ニンジンは何科の野菜？', c: ['セリ科', 'アブラナ科', 'キク科', 'ナス科'], e: 'セリ科にはセルリー・パセリ・ミツバなどがある。ニンジンの種子は好光性なので覆土は薄くする。' },
  { id: 'v05', f: 'veg', q: 'レタスは何科の野菜？', c: ['キク科', 'アブラナ科', 'セリ科', 'ヒユ科'], e: 'キク科にはゴボウ・シュンギク・フキなどがある。レタスの種子も好光性。' },
  { id: 'v06', f: 'veg', q: 'ホウレンソウは何科の野菜？', c: ['ヒユ科', 'アブラナ科', 'キク科', 'セリ科'], e: '旧分類（新エングラー体系）ではアカザ科。酸性土壌に弱いので、石灰で酸度を矯正してから栽培する。' },
  { id: 'v07', f: 'veg', q: 'オクラは何科の野菜？', c: ['アオイ科', 'ナス科', 'ウリ科', 'マメ科'], e: 'アオイ科。ハイビスカスやワタも同じ仲間で、よく似た花を咲かせる。' },
  { id: 'v08', f: 'veg', q: 'キャベツ・ハクサイ・ホウレンソウは、利用する部分による分類で何類？', c: ['葉菜類', '果菜類', '根菜類', '豆類'], e: '果菜類はトマト・キュウリなど果実を利用するもの、根菜類はダイコン・ニンジンなど地下部を利用するもの。' },
  { id: 'v09', f: 'veg', q: 'ブロッコリーで主に食べている部分は？', c: ['花蕾（つぼみ）', '葉', '根', '果実'], e: 'ブロッコリーやカリフラワーは花のつぼみの集まり（花蕾）を食べる「花菜類」。' },
  { id: 'v10', f: 'veg', q: 'トマトの果実のおしり（花落ち部）が黒くへこむ「尻腐れ果」の主な原因は？', c: ['カルシウム欠乏', '窒素過多による病原菌', 'リン酸欠乏', 'マグネシウム欠乏'], e: '土壌の乾燥や窒素・カリの多施用でカルシウムの吸収が妨げられて起こる「生理障害」。病原菌によるものではない。' },
  { id: 'v11', f: 'veg', q: 'トマトの葉のつけ根から出るわき芽をかき取る作業は？', c: ['芽かき', '摘心', '誘引', '摘果'], e: '主枝1本仕立てではわき芽を早めにかき取る。摘心は茎の先端を止める作業、誘引は茎をひもや支柱に結ぶ作業。' },
  { id: 'v12', f: 'veg', q: 'トマトの苗を定植するとき、第1花房はどちらに向けて植えるとよい？', c: ['通路側', 'ウネの内側', '北側', '向きは関係ない'], e: 'トマトの花房はほぼ同じ方向に着くため、第1花房を通路側に向けると管理・収穫がしやすい。' },
  { id: 'v13', f: 'veg', q: 'トマトの着果促進に使われるトマトトーン（4-CPA）は何系の植物生長調節剤？', c: ['オーキシン系', 'ジベレリン系', 'サイトカイニン系', 'エチレン系'], e: '低温期などで受粉・着果しにくいとき、花房に噴霧して着果を促す。' },
  { id: 'v14', f: 'veg', q: 'キュウリの果実の表面に付く白い粉の正体は？', c: ['ブルーム（果粉）', 'うどんこ病の病斑', '農薬の残留物', 'カルシウムの結晶'], e: 'ブルームは果実自身が出すケイ酸を主成分とする物質。ブルームレス台木のカボチャに接ぐと出にくく、つやのある果実になる。' },
  { id: 'v15', f: 'veg', q: 'キュウリの接ぎ木で、台木として最もよく使われるのは？', c: ['カボチャ', 'ユウガオ', 'ナス', 'トマト'], e: 'カボチャ台木でつる割病などの土壌病害を回避し、低温での生育も良くなる。スイカの台木にはユウガオなどが使われる。' },
  { id: 'v16', f: 'veg', q: '受粉しなくても果実が肥大する性質を何という？', c: ['単為結果', '自家不和合性', '雄性不稔', '抽だい'], e: 'キュウリの多くの品種は単為結果性をもつため、ハウス内でも受粉作業なしで収穫できる。' },
  { id: 'v17', f: 'veg', q: 'ナスの花で、雌しべが雄しべより長い、栄養状態の良い花を何という？', c: ['長花柱花', '短花柱花', '中花柱花', '不完全花'], e: '短花柱花が多いときは、肥料切れ・水不足・日照不足などのサイン。' },
  { id: 'v18', f: 'veg', q: 'ダイコンやハクサイが花芽をつけ、花茎が伸び出す現象を何という？', c: ['抽だい（とう立ち）', '分げつ', '結球', '徒長'], e: '低温や長日などの条件で花芽ができて花茎が伸びる。抽だいすると根や葉が硬くなり品質が下がる。' },
  { id: 'v19', f: 'veg', q: 'イチゴは何科の植物？', c: ['バラ科', 'ナス科', 'ウリ科', 'ユキノシタ科'], e: '食べる赤い部分は花托（花床）が肥大したもの。表面のツブツブが本当の果実（そう果）。' },
  { id: 'v20', f: 'veg', q: 'イチゴが子株を増やすために伸ばす茎を何という？', c: ['ランナー（ほふく茎）', '吸枝', '巻きひげ', '不定根'], e: 'ランナーの先にできる子株を採って苗にする（ランナー採苗）。' },
  { id: 'v21', f: 'veg', q: 'イチゴ（一季成り品種）の花芽分化を促す条件は？', c: ['低温・短日', '高温・長日', '高温・短日', '低温・長日'], e: '夜冷短日処理などで花芽分化を早め、年内（クリスマス）出荷につなげる。' },
  { id: 'v22', f: 'veg', q: 'ネギの白い部分（軟白部）を長くするために、株元へ土を寄せる作業は？', c: ['土寄せ（培土）', '中耕', 'マルチング', '間引き'], e: '土寄せで光を遮ると葉鞘部分が白く柔らかくなる（軟白）。' },
  { id: 'v23', f: 'veg', q: 'キャベツなどアブラナ科野菜の葉を食い荒らす「アオムシ」の成虫は？', c: ['モンシロチョウ', 'アゲハチョウ', 'ニジュウヤホシテントウ', 'アブラムシ'], e: 'アゲハチョウの仲間の幼虫は、ミカン科やセリ科（ニンジンなど）を食害する。' },
  { id: 'v24', f: 'veg', q: 'ナスやジャガイモの葉を網目状に食害する、「テントウムシダマシ」と呼ばれる害虫の代表種は？', c: ['ニジュウヤホシテントウ', 'ナナホシテントウ', 'ナミテントウ', 'ヒメカメノコテントウ'], e: 'オオニジュウヤホシテントウも含めてテントウムシダマシと総称する。ナナホシテントウやナミテントウはアブラムシを食べる益虫（天敵）。' },
  { id: 'v25', f: 'veg', q: 'トマト黄化葉巻病（ウイルス病）を媒介する害虫は？', c: ['タバココナジラミ', 'モモアカアブラムシ', 'ミナミキイロアザミウマ', 'ナミハダニ'], e: '防虫ネットで侵入を防いだり、黄色粘着板で捕殺したりする。発病株は早めに抜き取る。' },
  { id: 'v26', f: 'veg', q: '定植前の苗を、外気や低温に徐々に慣らして丈夫にすることを何という？', c: ['順化（ならし）', '鉢上げ', '摘心', '春化'], e: '育苗の最後に温度を下げたり水を控えたりして、植え付け後の環境に耐えられる苗にする。' },
  { id: 'v27', f: 'veg', q: 'セル成型苗（プラグ苗）を育てる、小さな穴が多数並んだ育苗容器は？', c: ['セルトレイ', '育苗箱', 'ポリポット', 'プランター'], e: 'セルトレイで育てた苗は根鉢が崩れにくく、機械移植にも向く。' },
  { id: 'v28', f: 'veg', q: 'ウネの表面をポリエチレンフィルムなどで覆い、地温上昇・雑草抑制・土壌水分の保持をはかることを何という？', c: ['マルチング', 'トンネル被覆', 'べたがけ', '遮光'], e: '黒色マルチは雑草抑制効果、透明マルチは地温上昇効果が高い。' },
  { id: 'v29', f: 'veg', q: '連作障害が特に出やすく、4〜5年は同じ場所での栽培を避けるとよい野菜は？', c: ['エンドウ', 'カボチャ', 'サツマイモ', 'タマネギ'], e: 'エンドウは連作に非常に弱い。スイカやナス科野菜も連作障害に注意が必要。' },
  { id: 'v30', f: 'veg', q: '発芽に光を必要とする「好光性種子」の野菜は？', c: ['レタス', 'ダイコン', 'トマト', 'ネギ'], e: 'レタス・ニンジン・ゴボウ・シソなどは好光性種子なので、覆土はごく薄くする。' },
  { id: 'v31', f: 'veg', q: 'タマネギで食べている部分は？', c: ['りん茎（鱗茎）', '塊根', '塊茎', '花蕾'], e: '葉の基部（りん葉）が肥大して重なったもの。タマネギは長日条件で球が肥大する。' },
  { id: 'v32', f: 'veg', q: 'ウリ科野菜の葉に、白い粉をふりかけたような斑点ができる糸状菌（カビ）の病気は？', c: ['うどんこ病', 'べと病', 'モザイク病', '青枯病'], e: 'カボチャ・キュウリ・メロンなどで発生しやすい。比較的乾燥した条件でも発生する。' },
  { id: 'v33', f: 'veg', q: 'トマトやナスの株が、青いまま急にしおれて枯れてしまう細菌による土壌病害は？', c: ['青枯病', 'うどんこ病', '灰色かび病', 'モザイク病'], e: '病原細菌が導管で増えて水の通り道をふさぐ。切った茎を水につけると白い汁（菌泥）が出る。抵抗性台木への接ぎ木で防ぐ。' },
  { id: 'v34', f: 'veg', q: 'アブラムシが媒介することが多く、葉にまだら模様が出て縮れるウイルス病は？', c: ['モザイク病', 'うどんこ病', '軟腐病', 'つる割病'], e: 'ウイルス病は治療できない。アブラムシの防除や、光を反射するシルバーマルチで飛来を防ぐことが大切。' },
  { id: 'v35', f: 'veg', q: '土を使わず、肥料を溶かした水（培養液）で野菜を育てる方法は？', c: ['養液栽培', '有機栽培', '露地栽培', '不耕起栽培'], e: '水耕・ロックウール耕などがある。土壌病害や連作障害を回避でき、施設園芸で広く使われる。球根を水だけで咲かせる「水栽培」とは違い、培養液で養分を与えるのがポイント。' },
  { id: 'v36', f: 'veg', q: 'スイートコーンの収穫適期の目安は、絹糸が出てから何日ごろ？', c: ['約20〜25日', '約3日', '約60日', '約100日'], e: '絹糸が褐色に枯れてきたころが目安。収穫後は糖度が急速に下がるので早めに食べる。' },
  { id: 'v37', f: 'veg', q: 'ハクサイやキャベツで、葉が重なり合って球状になることを何という？', c: ['結球', '抽だい', '分げつ', '登熟'], e: '冷涼な気候を好み、高温期には結球しにくい。' },
  { id: 'v38', f: 'veg', q: 'ホウレンソウを栽培する前に、酸性土壌を矯正するため施す資材は？', c: ['苦土石灰', '硫安', '過リン酸石灰', 'ピートモス'], e: '苦土石灰はカルシウムとマグネシウムを含み、土壌のpHを上げる。施用後1〜2週間おいてから種まきする。' },
  { id: 'v39', f: 'veg', q: '種子をまいた後、発芽をそろえるために土を軽く押さえる作業は？', c: ['鎮圧', '中耕', '土寄せ', '間引き'], e: '種子と土を密着させて水分を吸収しやすくし、発芽をそろえる。' },
  { id: 'v40', f: 'veg', q: '生育をそろえるため、混み合った芽を抜き取って株間を広げる作業は？', c: ['間引き', '摘心', '芽かき', '摘果'], e: 'ダイコンやニンジンなど直まきの野菜では、生育に合わせて数回に分けて間引く。' },

  // ================= 草花 =================
  { id: 'f01', f: 'flower', q: 'キクは日長反応でいうと何植物？', c: ['短日植物', '長日植物', '中性植物', '低温植物'], e: '日が短く（夜が長く）なると花芽を形成する。秋に咲くのはこのため。' },
  { id: 'f02', f: 'flower', q: 'キクの開花を遅らせるため、夜間に電灯をつけて暗期を中断する栽培法は？', c: ['電照栽培', 'シェード栽培', '水耕栽培', '露地栽培'], e: '花芽分化を抑えて出荷時期を調節する。愛知県の電照ギクが有名。' },
  { id: 'f03', f: 'flower', q: 'キクを夕方から朝まで黒いフィルムで覆って短日条件をつくり、開花を早める栽培法は？', c: ['シェード栽培', '電照栽培', '雨よけ栽培', '養液栽培'], e: '短日植物は暗期を長くすると花芽分化が進む。秋ギクを夏〜初秋に開花・出荷させる作型などで行う。' },
  { id: 'f04', f: 'flower', q: 'カーネーションは何科の草花？', c: ['ナデシコ科', 'キク科', 'バラ科', 'アブラナ科'], e: 'ナデシコ科。母の日の花として有名で、主に挿し芽で増やす。' },
  { id: 'f05', f: 'flower', q: 'パンジーは何科の草花？', c: ['スミレ科', 'キク科', 'シソ科', 'サクラソウ科'], e: 'スミレ科。秋にまいて冬〜春に咲く代表的な花壇苗。' },
  { id: 'f06', f: 'flower', q: 'ペチュニアは何科の草花？', c: ['ナス科', 'キク科', 'シソ科', 'ヒルガオ科'], e: 'ナス科。種子がとても小さく好光性なので、覆土しないでまく。' },
  { id: 'f07', f: 'flower', q: 'マリーゴールドは何科の草花？', c: ['キク科', 'シソ科', 'ナス科', 'スミレ科'], e: 'キク科。根からセンチュウを抑える物質を出すため、センチュウ対策の対抗植物としても使われる。' },
  { id: 'f08', f: 'flower', q: 'サルビアは何科の草花？', c: ['シソ科', 'キク科', 'ナス科', 'ナデシコ科'], e: 'シソ科。茎の断面が四角いのがシソ科の特徴。' },
  { id: 'f09', f: 'flower', q: 'チューリップの球根は、形態上どれに分類される？', c: ['りん茎（鱗茎）', '球茎', '塊茎', '塊根'], e: '短縮した茎に、養分を蓄えたりん片葉が重なったもの。ユリ・スイセン・ヒヤシンスもりん茎。' },
  { id: 'f10', f: 'flower', q: 'グラジオラスの球根は、形態上どれに分類される？', c: ['球茎', 'りん茎', '塊根', '根茎'], e: '茎の基部が球状に肥大したもの。フリージア・クロッカスも球茎。' },
  { id: 'f11', f: 'flower', q: 'ダリアの球根は、形態上どれに分類される？', c: ['塊根', '球茎', 'りん茎', '塊茎'], e: '根が肥大したもの。芽は根ではなく茎の基部（クラウン）にあるので、分けるときは芽をつけて分ける。' },
  { id: 'f12', f: 'flower', q: 'シクラメンの球根は、形態上どれに分類される？', c: ['塊茎', '塊根', 'りん茎', '球茎'], e: '胚軸が肥大した塊茎をもつ。冬の鉢花の代表で、サクラソウ科。' },
  { id: 'f13', f: 'flower', q: 'ポインセチアの苞（ほう）が赤く色づくために必要な日長条件は？', c: ['短日条件', '長日条件', '日長は関係ない', '24時間の連続照明'], e: '短日植物。夕方から朝まで暗くする短日処理で、クリスマスに合わせて色づかせる。トウダイグサ科。' },
  { id: 'f14', f: 'flower', q: '次のうち「長日植物」はどれ？', c: ['カスミソウ', 'キク', 'ポインセチア', 'アサガオ'], e: 'カスミソウは日が長くなると花芽をつける長日植物。キク・ポインセチア・アサガオは短日植物。' },
  { id: 'f15', f: 'flower', q: '冬に地上部が枯れても、地下の根や芽が生き残って毎年花を咲かせる草花を何という？', c: ['宿根草', '一年草', '二年草', '球根植物'], e: '例：キキョウ・シャクヤク・ルドベキアなど。植えっぱなしで毎年楽しめる。' },
  { id: 'f16', f: 'flower', q: '次のうち、秋まき一年草として扱われるのはどれ？', c: ['パンジー', 'マリーゴールド', 'サルビア', 'ヒマワリ'], e: 'パンジー・ビオラ・キンセンカなどは秋まき。マリーゴールド・サルビア・ヒマワリは春まき一年草。' },
  { id: 'f17', f: 'flower', q: '好光性種子（光発芽種子）の草花をまくときの覆土は？', c: ['ごく薄くするか、しない', '種子の直径の5倍程度', '厚くかけて光をさえぎる', '黒いフィルムで覆う'], e: 'ペチュニア・ベゴニア・プリムラなどの好光性種子は、光が当たらないと発芽しにくい。' },
  { id: 'f18', f: 'flower', q: '光によって発芽が抑えられる「嫌光性種子」の草花はどれ？', c: ['ケイトウ', 'ペチュニア', 'ベゴニア', 'プリムラ'], e: 'ケイトウ・ニチニチソウなどは嫌光性種子なので、しっかり覆土する。' },
  { id: 'f19', f: 'flower', q: '挿し木・株分け・接ぎ木・分球など、種子によらない繁殖方法の総称は？', c: ['栄養繁殖', '種子繁殖', '有性繁殖', '実生繁殖'], e: '親と同じ性質の株を増やせるのが長所。ただしウイルス病なども親から引き継いでしまう。' },
  { id: 'f20', f: 'flower', q: '茎の先端（頂芽）を摘み取り、わき芽を伸ばして枝数を増やす作業は？', c: ['摘心（ピンチ）', '摘蕾', '芽かき', '切り戻し'], e: '枝数・花数が増え、こんもりとした草姿になる。' },
  { id: 'f21', f: 'flower', q: '茎の先端の芽が優先的に伸び、わき芽の伸長が抑えられる性質を何という？', c: ['頂芽優勢', '屈光性', '春化', '休眠'], e: '頂芽でつくられるオーキシンがわき芽の伸長を抑えている。摘心するとわき芽が伸び出す。' },
  { id: 'f22', f: 'flower', q: '赤・紫・青などの花色のもとになる、水溶性の色素は？', c: ['アントシアニン', 'クロロフィル', 'カロテノイド', 'タンニン'], e: 'アントシアニンはpHや金属イオンで色が変わる。黄〜橙色はカロテノイド（脂溶性）によることが多い。' },
  { id: 'f23', f: 'flower', q: 'キクが開花後の冬に株元から伸ばす、翌年の親株となる芽を何という？', c: ['冬至芽', '頂芽', '不定芽', '花芽'], e: '冬至芽を育てて親株にし、そこから穂を採って挿し芽で増やす。' },
  { id: 'f24', f: 'flower', q: '切り花用カーネーションの苗の主な増やし方は？', c: ['挿し芽', '種子', '株分け', '分球'], e: '親株から採った芽（穂）を挿して発根させる。ウイルスフリー苗の利用も重要。' },
  { id: 'f25', f: 'flower', q: '切り花の茎を水中で切り、切り口から空気が入らないようにして水の吸い上げをよくする方法は？', c: ['水切り', '湯揚げ', '焼き揚げ', '逆さ水'], e: '空気中で切ると導管に空気が入り、水が上がりにくくなる。湯揚げは切り口を熱湯につける方法。' },
  { id: 'f26', f: 'flower', q: 'カーネーションの切り花の日持ちを良くするため、エチレンの作用を抑える目的で使う薬剤は？', c: ['STS（チオ硫酸銀錯塩）', 'ジベレリン', '尿素', '消石灰'], e: 'カーネーションはエチレンに敏感で、花弁が内側に巻き込む「眠り病」が起こる。STS前処理で日持ちが大きく向上する。' },
  { id: 'f27', f: 'flower', q: '秋に植え付け、冬の低温にあたって春に開花する「秋植え球根」はどれ？', c: ['チューリップ', 'グラジオラス', 'ダリア', 'カンナ'], e: 'チューリップ・ヒヤシンス・スイセン・クロッカスは秋植え。グラジオラス・ダリア・カンナは春植え球根。' },
  { id: 'f28', f: 'flower', q: 'コチョウランのように、樹木の幹や岩に根を張って生育するランを何という？', c: ['着生ラン', '地生ラン', '腐生ラン', '水生ラン'], e: '根は空気中の水分も吸収できる。鉢植えでは水ごけやバークで植える。' },
  { id: 'f29', f: 'flower', q: 'ヒマワリは何科の草花？', c: ['キク科', 'アオイ科', 'ナス科', 'シソ科'], e: '一つの花に見えるのは、小さな花（管状花と舌状花）がたくさん集まった頭状花序。' },
  { id: 'f30', f: 'flower', q: 'アサガオは何科の草花？', c: ['ヒルガオ科', 'ナス科', 'キク科', 'ウリ科'], e: 'サツマイモも同じヒルガオ科。アサガオは短日植物で、日長反応の観察教材によく使われる。' },
  { id: 'f31', f: 'flower', q: '花壇苗の育成や出荷に使われる、ポリエチレン製の黒い小さな鉢は？', c: ['ポリポット', 'プランター', '素焼き鉢', 'ハンギングバスケット'], e: '安価で軽く、苗の生産に広く使われる。大きさは号数（1号＝約3cm）で表す。' },
  { id: 'f32', f: 'flower', q: '鉢の大きさを表す「号」。5号鉢の直径は約何cm？', c: ['約15cm', '約5cm', '約10cm', '約50cm'], e: '1号＝1寸＝約3cm。5号鉢は直径約15cm。' },
  { id: 'f33', f: 'flower', q: '広葉樹の落ち葉を腐らせてつくる、通気性・保水性を高める有機質の用土は？', c: ['腐葉土', '鹿沼土', 'バーミキュライト', 'パーライト'], e: '鹿沼土は酸性の軽石、バーミキュライトとパーライトは鉱物を高温処理した人工用土。' },
  { id: 'f34', f: 'flower', q: 'ツツジやサツキの栽培によく使われる、酸性で通気性の良い黄色い軽石状の用土は？', c: ['鹿沼土', '赤玉土', '腐葉土', '黒土'], e: '栃木県鹿沼地方で産出される。酸性を好むツツジ類やブルーベリーに適する。' },
  { id: 'f35', f: 'flower', q: '花弁や茎に灰色のカビが生え、多湿条件で多発する病気は？', c: ['灰色かび病', 'うどんこ病', '白さび病', '立枯病'], e: 'ボトリチス病ともいう。咲き終わった花がらを早めに取り除き、風通しを良くして防ぐ。' },
  { id: 'f36', f: 'flower', q: '咲き終わった花を摘み取る作業を何という？', c: ['花がら摘み', '摘心', '摘蕾', '誘引'], e: '種子をつくるために使われる養分を節約して次の花を咲かせる。病気の予防にもなる。' },
  { id: 'f37', f: 'flower', q: 'シクラメンやポインセチアのように、鉢で育てて観賞・出荷する草花を何という？', c: ['鉢物', '切り花', '花壇苗', '地被植物'], e: '花き生産は「切り花」「鉢物」「花壇用苗もの」「球根」などに分けられる。' },
  { id: 'f38', f: 'flower', q: '交配の前に、自家受粉を防ぐため花から雄しべを取り除く作業は？', c: ['除雄', '摘心', '摘蕾', '誘引'], e: 'F1（一代雑種）品種の種子をとる採種では欠かせない作業。' },

  // ================= 果樹 =================
  { id: 'r01', f: 'fruit', q: 'リンゴは何科の果樹？', c: ['バラ科', 'ミカン科', 'ブドウ科', 'カキノキ科'], e: 'ナシ・モモ・ウメ・オウトウ・ビワもバラ科。' },
  { id: 'r02', f: 'fruit', q: 'ウンシュウミカンは何科の果樹？', c: ['ミカン科', 'バラ科', 'ムクロジ科', 'ツツジ科'], e: 'ミカン科カンキツ属。鹿児島県（長島）原産とされ、種子がほとんどできない。' },
  { id: 'r03', f: 'fruit', q: 'カキは何科の果樹？', c: ['カキノキ科', 'バラ科', 'ミカン科', 'クワ科'], e: '甘ガキと渋ガキがあり、富有・次郎は代表的な甘ガキ。' },
  { id: 'r04', f: 'fruit', q: 'ブドウは何科の果樹？', c: ['ブドウ科', 'バラ科', 'マタタビ科', 'クワ科'], e: 'つる性の果樹で、巻きひげで他物に絡みつく。日本では棚仕立てが多い。' },
  { id: 'r05', f: 'fruit', q: 'リンゴ・ナシ・ビワのように、花托（花床）が肥大して食用部分になる果実のグループは？', c: ['仁果類', '核果類', 'しょう果類（液果類）', '堅果類'], e: '子房以外の部分が発達した偽果。芯の部分が本来の子房にあたる。' },
  { id: 'r06', f: 'fruit', q: 'モモ・ウメ・スモモ・オウトウのように、内果皮が硬い核になる果実のグループは？', c: ['核果類', '仁果類', '堅果類', 'しょう果類（液果類）'], e: '食べる部分は中果皮。種子は硬い核の中にある。' },
  { id: 'r07', f: 'fruit', q: '果皮が多汁で柔らかい「しょう果類（液果類）」に分類される果樹は？', c: ['ブドウ', 'モモ', 'クリ', 'リンゴ'], e: 'ブドウ・キウイフルーツ・ブルーベリーなどが代表。クリは堅果類、モモは核果類、リンゴは仁果類。' },
  { id: 'r08', f: 'fruit', q: 'ニホンナシやリンゴは、同じ品種の花粉では受精しにくい。この性質を何という？', c: ['自家不和合性', '単為結果性', '隔年結果性', '雌雄異株'], e: 'そのため異なる品種を混植したり、別品種の花粉で人工受粉したりする。' },
  { id: 'r09', f: 'fruit', q: 'ナシの人工受粉で、花粉をつけて柱頭にふれるために使う、綿や羽毛でできた道具は？', c: ['梵天（ぼんてん）', '剪定ばさみ', '摘果ばさみ', '噴霧器'], e: '毛ばたきのような道具。最近は電動の受粉機も使われる。' },
  { id: 'r10', f: 'fruit', q: '果実が大きく品質良く育つよう、若い果実を間引く作業は？', c: ['摘果', '摘蕾', '摘心', '袋かけ'], e: '葉の数に対して果実数を適正にする（葉果比）。隔年結果の防止にもつながる。' },
  { id: 'r11', f: 'fruit', q: 'デラウェアなどのブドウを種なしにするため、花房を浸す植物ホルモン剤は？', c: ['ジベレリン', 'オーキシン', 'エチレン', 'アブシシン酸'], e: '開花前と開花後の2回処理が基本。1回目で種なし化、2回目で果粒を肥大させる。' },
  { id: 'r12', f: 'fruit', q: '日本で最も生産量の多いリンゴの品種は？', c: ['ふじ', 'つがる', '王林', 'ジョナゴールド'], e: '「国光」×「デリシャス」の交配で青森県藤崎町で育成された。世界でも広く栽培されている。' },
  { id: 'r13', f: 'fruit', q: '果皮が黄緑色の「青ナシ」の代表品種は？', c: ['二十世紀', '幸水', '豊水', '新高'], e: '鳥取県が主産地。幸水・豊水・新高は果皮が褐色の赤ナシ。' },
  { id: 'r14', f: 'fruit', q: 'ウンシュウミカンの台木として最も多く使われる植物は？', c: ['カラタチ', 'マルバカイドウ', 'ノイバラ', 'ヤマモモ'], e: 'カラタチ台は樹をコンパクトにし、果実の糖度を高める効果がある。' },
  { id: 'r15', f: 'fruit', q: 'リンゴのわい化栽培で使われる台木はどれ？', c: ['M.9（わい性台木）', 'カラタチ', 'ノイバラ', 'ユウガオ'], e: '樹を小さくまとめ、作業の省力化と早期多収をねらう。日本ではJM系台木も育成されている。' },
  { id: 'r16', f: 'fruit', q: '落葉果樹の骨格をつくる主な剪定（整枝・剪定）を行う時期は？', c: ['落葉後の休眠期（冬）', '開花期（春）', '果実肥大期（夏）', '収穫期（秋）'], e: '冬季剪定が基本。夏には徒長枝の整理などの夏季剪定を行うこともある。' },
  { id: 'r17', f: 'fruit', q: '果実がたくさんなる年（表年）と少ない年（裏年）が交互にくり返される現象は？', c: ['隔年結果', '単為結果', '自家結実', '生理落果'], e: 'なり過ぎで樹の養分が不足し、翌年の花芽が少なくなるのが原因。適正な摘果で防ぐ。' },
  { id: 'r18', f: 'fruit', q: 'カキの渋みのもとになる成分は？', c: ['タンニン（シブオール）', 'アントシアニン', 'クエン酸', 'ソルビトール'], e: '水溶性のタンニンが舌で溶けて渋く感じる。渋抜きはタンニンを不溶性に変える処理。' },
  { id: 'r19', f: 'fruit', q: '渋ガキの渋抜きの方法として正しいものは？', c: ['アルコールや炭酸ガスで処理する', '冷蔵庫で冷やす', 'ジベレリンで処理する', '石灰をまぶす'], e: 'アルコール脱渋・炭酸ガス脱渋のほか、皮をむいて干す「干し柿」でも渋が抜ける。' },
  { id: 'r20', f: 'fruit', q: '甘ガキの代表品種はどれ？', c: ['富有', '平核無', '刀根早生', '西条'], e: '富有・次郎は完全甘ガキ。平核無・刀根早生・西条は渋ガキ。' },
  { id: 'r21', f: 'fruit', q: '枝の途中で切り詰めて、残した芽から強い新梢を出させる剪定方法は？', c: ['切り返し剪定', '間引き剪定', '芽かき', '環状剥皮'], e: '間引き剪定は枝を付け根から切り取り、樹冠内部の日当たりや風通しをよくする方法。' },
  { id: 'r22', f: 'fruit', q: 'キウイフルーツは雌木と雄木が別々の個体になっている。この性質は？', c: ['雌雄異株', '雌雄同株', '両性花', '単為結果'], e: '実がなるのは雌木だけ。受粉用の雄木を混植するか人工受粉する。マタタビ科。' },
  { id: 'r23', f: 'fruit', q: 'ブルーベリーが好む土壌は？', c: ['酸性土壌（pH4.5〜5.5程度）', 'アルカリ性土壌（pH8程度）', '中性土壌（pH7程度）', 'pHは関係ない'], e: 'ツツジ科で酸性土壌を好む。植え付け時にピートモスを混ぜて酸度を調整する。' },
  { id: 'r24', f: 'fruit', q: '果汁をのせて、光の屈折から糖度（Brix値）を測る器具は？', c: ['屈折糖度計', 'pHメーター', '照度計', '土壌水分計'], e: '近年は果実を傷つけずに糖度を測る光センサー（非破壊選果機）も普及している。' },
  { id: 'r25', f: 'fruit', q: 'モモなどで、主幹を低い位置で切り、2〜3本の主枝を斜めに伸ばして樹の内部に日光を入れる仕立て方は？', c: ['開心自然形', '主幹形', '平棚仕立て', '垣根仕立て'], e: 'モモ・ウメ・カキなどで用いられる。ブドウやナシでは棚仕立ても多い。' },
  { id: 'r26', f: 'fruit', q: 'リンゴの「蜜入り」の蜜の正体となる糖アルコールは？', c: ['ソルビトール', 'デンプン', 'タンニン', 'クエン酸'], e: '葉でつくられ果実に運ばれたソルビトールが、果糖などに変わらず細胞のすき間にたまった状態。' },
  { id: 'r27', f: 'fruit', q: '受精不良や養分競合などにより、病害虫によらず幼果が自然に落ちる現象は？', c: ['生理落果', '隔年結果', '自家不和合', '裂果'], e: 'カキやカンキツで多い。6月頃の落果は「ジューンドロップ」と呼ばれる。' },
  { id: 'r28', f: 'fruit', q: '皮ごと食べられ、黄緑色の果皮をもつ近年人気の大粒ブドウ品種（農研機構育成）は？', c: ['シャインマスカット', '巨峰', 'デラウェア', 'ピオーネ'], e: '2006年に品種登録。巨峰・ピオーネは紫黒色の大粒品種、デラウェアは小粒の赤色品種。' },
  { id: 'r29', f: 'fruit', q: '台木に品種の穂木をつないで苗木を増やす方法は？', c: ['接ぎ木', '挿し木', '取り木', '実生'], e: '果樹の苗木の多くは接ぎ木でつくる。台木の性質で樹の大きさや病害抵抗性を調整できる。' },
  { id: 'r30', f: 'fruit', q: 'ビワは何科の果樹？', c: ['バラ科', 'ミカン科', 'ツバキ科', 'カキノキ科'], e: '冬に開花し、初夏に収穫する常緑果樹。長崎県・千葉県などが主産地。' },
  { id: 'r31', f: 'fruit', q: 'リンゴやナシで行う「袋かけ」の主な目的は？', c: ['病害虫から果実を守り、外観を良くする', '果実の糖度を急激に上げる', '受粉を助ける', '果実を早く落とす'], e: '省力化のため、袋をかけない無袋栽培（例：サンふじ）も増えている。' },
  { id: 'r32', f: 'fruit', q: '「ゴールド二十世紀」は、二十世紀にどんな方法で黒斑病抵抗性をもたせた品種？', c: ['放射線照射による突然変異育種', '交雑育種', '遺伝子組換え', '接ぎ木'], e: '茨城県の放射線育種場で、ガンマ線照射による突然変異を利用して育成された。' },
  { id: 'r33', f: 'fruit', q: '果樹の芽のうち、一般に丸くふくらんで大きいものはどれ？', c: ['花芽', '葉芽', 'どちらも同じ', '不定芽'], e: '剪定では花芽の数を確認しながら、残す枝を決める。' },
  { id: 'r34', f: 'fruit', q: '大粒ブドウで、果粒を間引いて房の形を整え、粒を大きくする作業は？', c: ['摘粒', '摘心', '芽かき', '誘引'], e: '巨峰やシャインマスカットなどでは、品種ごとの目標粒数に整える。' },
  { id: 'r35', f: 'fruit', q: '果樹園の地面に草を生やして管理し、土壌流亡の防止や有機物の補給をはかる方法は？', c: ['草生栽培', '清耕栽培', '養液栽培', '雨よけ栽培'], e: '清耕栽培は除草して地面をむき出しにする方法。草生栽培では刈った草を敷き草として利用する。' },
  { id: 'r36', f: 'fruit', q: 'カンキツ類の果皮や葉に、かさぶた状の病斑ができる病気は？', c: ['そうか病', '黒星病', '赤星病', '縮葉病'], e: '黒星病・赤星病はナシ、縮葉病はモモの代表的な病気。' },
  { id: 'r37', f: 'fruit', q: 'ナシ赤星病の中間宿主となるため、ナシ園の近くに植えないほうがよい植物は？', c: ['ビャクシン類（カイヅカイブキなど）', 'カラタチ', 'ノイバラ', 'クワ'], e: '赤星病菌はナシとビャクシン類の間を行き来して生活している。' },
  { id: 'r38', f: 'fruit', q: '収穫した果実を一定期間おいて、やわらかく甘い食べごろにすることを何という？', c: ['追熟', '登熟', '休眠', '脱渋'], e: '西洋ナシ・キウイフルーツ・バナナなどは追熟が必要。キウイはエチレン処理で追熟を促す。' },
  { id: 'r39', f: 'fruit', q: 'モモの葉が赤くふくれて縮れる、春先に多い病気は？', c: ['縮葉病', 'そうか病', '赤星病', 'うどんこ病'], e: '発芽前の休眠期に薬剤を散布して予防する。' },

  // ================= 作物 =================
  { id: 'c01', f: 'crop', q: 'イネの「塩水選」の目的は？', c: ['充実した重い種もみを選ぶ', '種もみを消毒する', '種もみに吸水させる', '種もみを乾燥させる'], e: '塩水に沈んだ充実した種もみを使い、浮いたものは取り除く。' },
  { id: 'c02', f: 'crop', q: 'うるち種の塩水選で用いる塩水の比重は？', c: ['1.13', '1.03', '1.30', '1.50'], e: 'もち種は1.08程度。比重計で確認しながら調整する。' },
  { id: 'c03', f: 'crop', q: '種もみの浸種で、十分に吸水させる目安となる水温の積算温度は？', c: ['約100℃', '約10℃', '約1000℃', '約3000℃'], e: '水温10℃なら約10日、15℃なら約7日が目安。均一に吸水させて発芽をそろえる。' },
  { id: 'c04', f: 'crop', q: '催芽で、芽がわずかに出た（約1mm）播種に適した状態を何という？', c: ['ハト胸状態', '出穂状態', '分げつ状態', '登熟状態'], e: '30〜32℃程度で催芽する。芽が伸びすぎると播種機で傷みやすい。' },
  { id: 'c05', f: 'crop', q: '田植機用に育てる、葉齢2.0〜2.5葉程度の苗を何という？', c: ['稚苗', '中苗', '成苗', 'ポット苗'], e: '稚苗は育苗期間が約20日と短い。中苗は3〜4葉、成苗は5葉程度以上。' },
  { id: 'c06', f: 'crop', q: 'イネの茎の根元の節から、新しい茎が出てくることを何という？', c: ['分げつ', '出穂', '登熟', '抽だい'], e: '分げつのうち、穂をつけるものを有効分げつ、穂をつけないものを無効分げつという。' },
  { id: 'c07', f: 'crop', q: '田植え後1か月頃、田の水を落として土にひびが入る程度まで乾かす「中干し」の主な目的は？', c: ['無効分げつを抑え、根を健全にする', '雑草を枯らす', '肥料を流し出す', '害虫を追い出す'], e: '土中に酸素を入れて有害ガスを抜き、根の活力を高める。倒伏防止にも効果がある。' },
  { id: 'c08', f: 'crop', q: '糸状菌（カビ）によって葉や穂に病斑ができ、低温・多湿・窒素過多で多発するイネの重要病害は？', c: ['いもち病', '紋枯病', 'ばか苗病', '白葉枯病'], e: '葉いもち・穂いもちがあり、穂いもちは大きな減収につながる。抵抗性品種や適正な施肥で防ぐ。' },
  { id: 'c09', f: 'crop', q: '種子伝染し、苗が異常に徒長して黄化するイネの病気は？（原因菌がジベレリンをつくる）', c: ['ばか苗病', 'いもち病', '縞葉枯病', '紋枯病'], e: 'ジベレリン発見のきっかけになった病気。種子消毒で予防する。' },
  { id: 'c10', f: 'crop', q: '梅雨時期に海外から気流に乗って飛来し、イネの株元で汁を吸って「坪枯れ」を起こす害虫は？', c: ['トビイロウンカ', 'イネミズゾウムシ', 'ニカメイガ', 'スクミリンゴガイ'], e: 'トビイロウンカは日本では越冬できず、毎年海外から飛来する。' },
  { id: 'c11', f: 'crop', q: 'イネと水田雑草のノビエ（ヒエ）を見分けるポイントは？', c: ['イネには葉耳・葉舌があり、ヒエにはない', 'ヒエには葉耳・葉舌があり、イネにはない', 'どちらにも葉耳・葉舌がある', 'どちらにも葉耳・葉舌がない'], e: '葉身と葉鞘の境目を見る。農業鑑定でも定番の見分け方。' },
  { id: 'c12', f: 'crop', q: '出穂・開花後、デンプンが蓄積されて米粒が充実していく過程を何という？', c: ['登熟', '出穂', '分げつ', '幼穂形成'], e: '登熟期の天候（日照・気温）が収量と品質に大きく影響する。高温だと白未熟粒が増える。' },
  { id: 'c13', f: 'crop', q: '幼穂形成期（出穂の約25日前）頃に施す追肥を何という？', c: ['穂肥', '元肥', '分げつ肥', '実肥'], e: '籾数を確保し登熟を良くする。多すぎると倒伏や食味低下の原因になる。' },
  { id: 'c14', f: 'crop', q: '籾すりをして、籾殻を取り除いた状態の米を何という？', c: ['玄米', '精白米', '籾', '胚芽米'], e: '玄米からぬか層と胚芽を取り除いたものが精白米（白米）。' },
  { id: 'c15', f: 'crop', q: '全国で作付面積が最も大きい水稲品種は？', c: ['コシヒカリ', 'ひとめぼれ', 'ヒノヒカリ', 'あきたこまち'], e: '1956年に福井県で育成された。長年にわたり作付面積第1位を続けている。' },
  { id: 'c16', f: 'crop', q: 'もち米のデンプンは、ほぼ100%が何でできている？', c: ['アミロペクチン', 'アミロース', 'グルテン', 'セルロース'], e: 'うるち米はアミロース約20%・アミロペクチン約80%。アミロースが少ないほど粘りが強い。' },
  { id: 'c17', f: 'crop', q: 'ダイズなどマメ科植物の根にこぶをつくり、空気中の窒素を固定する微生物は？', c: ['根粒菌', '乳酸菌', '納豆菌', 'こうじ菌'], e: '根粒菌が固定した窒素をダイズが利用できるため、窒素肥料は少なめでよい。' },
  { id: 'c18', f: 'crop', q: 'ムギの「麦踏み」の主な目的は？', c: ['霜柱による浮き上がりを防ぎ、根張りを良くする', '雑草の種子を土に埋める', '穂を早く出させる', '土をやわらかくする'], e: '冬〜早春に行う。徒長を抑え、分げつを促進する効果もある。' },
  { id: 'c19', f: 'crop', q: 'たんぱく質（グルテン）が多い小麦粉「強力粉」の主な用途は？', c: ['パン', 'うどん', 'ケーキ', '天ぷらの衣'], e: '強力粉＝パン、中力粉＝うどん、薄力粉＝ケーキ・天ぷら。' },
  { id: 'c20', f: 'crop', q: '主にビールの原料として使われる麦は？', c: ['二条大麦', '六条大麦', 'はだか麦', 'ライ麦'], e: '穂に粒が2列に並ぶ。六条大麦は麦茶や押し麦などに使われる。' },
  { id: 'c21', f: 'crop', q: 'サツマイモは何科の作物？', c: ['ヒルガオ科', 'ナス科', 'サトイモ科', 'ヤマノイモ科'], e: '食べる部分は根が肥大した塊根。つるを切った「挿し苗」で植え付ける。' },
  { id: 'c22', f: 'crop', q: 'ジャガイモで食べている部分は？', c: ['塊茎', '塊根', 'りん茎', '球茎'], e: '地下の茎（ストロン）の先が肥大したもの。表面のくぼみ（目）に芽がある。種いもで増やす。' },
  { id: 'c23', f: 'crop', q: 'ジャガイモの芽や、光に当たって緑色になった部分に多く含まれる有毒成分は？', c: ['ソラニン（グリコアルカロイド）', 'カフェイン', 'タンニン', 'カプサイシン'], e: '食べると腹痛や吐き気を起こす。芽や緑色の部分は厚めに取り除き、保存は冷暗所で。' },
  { id: 'c24', f: 'crop', q: 'トウモロコシの雌穂の先から出る「絹糸（ひげ）」の正体は？', c: ['雌しべ（花柱）', '雄しべ', '葉の一部', '根'], e: '絹糸1本1本が粒につながっている。受粉しないと粒が欠ける。雄穂は茎の先端につく。' },
  { id: 'c25', f: 'crop', q: 'トウモロコシやサトウキビのように、高温・強光下で光合成の効率が高い植物を何という？', c: ['C4植物', 'C3植物', 'CAM植物', '寄生植物'], e: 'イネ・コムギ・ダイズはC3植物。パイナップルなどはCAM植物。' },
  { id: 'c26', f: 'crop', q: '肥料の三要素はどれ？', c: ['窒素・リン酸・カリ', '窒素・カルシウム・鉄', 'リン酸・マグネシウム・硫黄', 'カリ・カルシウム・マグネシウム'], e: '窒素は葉や茎（葉肥）、リン酸は花や実（実肥）、カリは根（根肥）の生育を助けるといわれる。' },
  { id: 'c27', f: 'crop', q: 'イネの倒伏（たおれ）の大きな原因となるものは？', c: ['窒素肥料のやりすぎ', 'リン酸肥料の不足', '中干しのしすぎ', '土寄せのしすぎ'], e: '窒素過多で茎が軟弱に長く伸びると倒れやすい。中干しは倒伏防止に効果がある。' },
  { id: 'c28', f: 'crop', q: 'ソバは何科の作物？', c: ['タデ科', 'イネ科', 'マメ科', 'ヒユ科'], e: '生育期間が70〜80日程度と短く、やせ地でも育つ。' },
  { id: 'c29', f: 'crop', q: 'お茶の原料になるチャ（茶）は何科の植物？', c: ['ツバキ科', 'ミカン科', 'モクセイ科', 'アオイ科'], e: '新芽を蒸して揉むと緑茶、発酵させると紅茶になる。主産地は静岡県・鹿児島県。' },
  { id: 'c30', f: 'crop', q: '田植機用の苗を育てる、縦約60cm×横約30cmの箱を何という？', c: ['育苗箱', 'セルトレイ', 'コンテナ', 'ポリポット'], e: '10aあたり約20箱が目安（稚苗の場合）。' },
  { id: 'c31', f: 'crop', q: '同じ田畑で1年間に異なる2種類の作物を栽培すること（例：イネの後にムギ）を何という？', c: ['二毛作', '二期作', '輪作', '間作'], e: '同じ作物を年2回つくるのは二期作。' },
  { id: 'c32', f: 'crop', q: '同じ畑で異なる種類の作物を順番に栽培し、連作障害を防ぐ方法は？', c: ['輪作', '連作', '混作', '二期作'], e: '北海道の畑作では、てんさい・ジャガイモ・豆類・小麦などの輪作が行われている。' },
  { id: 'c33', f: 'crop', q: '田植え前に田に水を入れ、土を砕いて平らにならす作業は？', c: ['代かき', '中干し', '畦塗り', '溝切り'], e: '漏水を防ぎ、苗の植え付けを均一にする。雑草を抑える効果もある。' },
  { id: 'c34', f: 'crop', q: '田のあぜ（畦畔）に泥を塗りつけて、水漏れを防ぐ作業は？', c: ['畦塗り', '代かき', '中干し', '溝切り'], e: '畦塗り機をトラクターに取り付けて作業することも多い。' },
  { id: 'c35', f: 'crop', q: 'イネの刈り取りと脱穀を同時に行う農業機械は？', c: ['コンバイン', 'バインダー', '田植機', 'ロータリー'], e: 'バインダーは刈り取って束ねるだけの機械。束ねたイネははさ掛けなどで乾燥させる。' },
  { id: 'c36', f: 'crop', q: '収穫したもみの水分を、貯蔵に適した約15%まで下げる作業は？', c: ['乾燥', '精米', '籾すり', '浸種'], e: '高温で急激に乾かすと米粒にひびが入る「胴割れ米」が発生するので、ゆっくり乾燥させる。' },
  { id: 'c37', f: 'crop', q: 'ダイズの未熟な莢を収穫して食べるものを何という？', c: ['エダマメ', 'モヤシ', '納豆', 'きな粉'], e: 'エダマメは野菜として扱われる。' },
  { id: 'c38', f: 'crop', q: 'コムギなどが、一定期間低温にあうことで花芽をつけるようになる性質を何という？', c: ['春化（バーナリゼーション）', '休眠', '登熟', '分げつ'], e: '秋まき性の強い品種は、冬の低温にあわないと出穂しない。' },
  { id: 'c39', f: 'crop', q: 'イネの「出穂」とはどんな状態？', c: ['止葉の葉鞘から穂が出ること', '根元から新しい茎が出ること', '種もみから芽が出ること', '米粒にデンプンがたまること'], e: '出穂後に開花・受粉し、登熟期に入る。全体の40〜50%が出穂した日を出穂期という。' },
  { id: 'c40', f: 'crop', q: 'サトウキビとともに砂糖の原料となり、北海道で栽培される作物は？', c: ['てんさい（ビート）', 'ジャガイモ', 'ダイズ', 'ソバ'], e: 'ヒユ科（旧アカザ科）で、根に糖分を蓄える。' },
  // ----- 野菜（追加） -----
  { id: 'v41', f: 'veg', q: 'ゴボウは何科の野菜？', c: ['キク科', 'セリ科', 'アブラナ科', 'ヒユ科'], e: 'キク科。長い根を食べる根菜類で、深く耕す必要がある。' },
  { id: 'v42', f: 'veg', q: 'インゲンマメ・エンドウ・ソラマメは何科の野菜？', c: ['マメ科', 'ナス科', 'ウリ科', 'アオイ科'], e: 'マメ科の野菜は根粒菌と共生し、空気中の窒素を利用できる。' },
  { id: 'v43', f: 'veg', q: 'サトイモで食べている部分は？', c: ['球茎', '塊根', 'りん茎', '塊茎'], e: '親いもの周りに子いも・孫いもができる。サトイモ科で、乾燥に弱い。' },
  { id: 'v44', f: 'veg', q: 'レンコン（ハス）で食べている部分は？', c: ['地下茎（根茎）', '根', '果実', '葉柄'], e: 'ハスの地下茎が肥大したもの。穴は泥の中の根に空気を送る通気孔。' },
  { id: 'v45', f: 'veg', q: 'アブラナ科野菜の重要害虫で、葉裏から食害して薄皮を残す「窓あき」状の食痕をつくる小さな蛾は？', c: ['コナガ', 'モンシロチョウ', 'ニジュウヤホシテントウ', 'タバココナジラミ'], e: '薬剤抵抗性が発達しやすいので、系統の異なる薬剤のローテーションや防虫ネットを組み合わせる。' },
  { id: 'v46', f: 'veg', q: 'キュウリの葉に葉脈で区切られた角ばった黄色の病斑ができ、多湿で発生しやすい病気は？', c: ['べと病', 'うどんこ病', '青枯病', 'モザイク病'], e: '葉裏に灰紫色のカビが生える。換気して湿度を下げることが大切。' },
  { id: 'v47', f: 'veg', q: 'ハクサイやキャベツの株元が溶けるように腐り、悪臭を出す細菌病は？', c: ['軟腐病', '根こぶ病', 'うどんこ病', 'モザイク病'], e: '傷口から細菌が侵入する。高温多湿で多発し、害虫の食害痕からも感染する。' },
  { id: 'v48', f: 'veg', q: 'アブラナ科野菜の根にこぶができ、生育が悪くなる土壌病害は？', c: ['根こぶ病', '青枯病', '軟腐病', 'べと病'], e: '酸性土壌で発生しやすい。石灰で土壌pHを上げたり、抵抗性品種（CR品種）を使ったりする。' },
  { id: 'v49', f: 'veg', q: 'トマトの果実が割れる「裂果」の主な原因は？', c: ['降雨などによる急な水分変化', 'カルシウム欠乏', '低温', '肥料不足'], e: '雨よけ栽培や、土壌水分を急に変化させない管理で防ぐ。' },
  { id: 'v50', f: 'veg', q: '冬の閉めきったハウス内で、光合成を促すために行う技術は？', c: ['炭酸ガス（CO₂）施用', '炭酸ガス脱渋', '遮光', '中干し'], e: '日中は光合成でハウス内のCO₂が不足しやすいため、発生機などで補給する。' },
  { id: 'v51', f: 'veg', q: 'ハウスの保温のため、内側にもう一枚フィルムを張ることを何という？', c: ['二重被覆（内張りカーテン）', 'マルチング', 'べたがけ', '雨よけ'], e: 'フィルムの間の空気層が断熱材の役割をし、暖房費の節約になる。' },
  { id: 'v52', f: 'veg', q: '「F1品種（一代雑種）」の特徴として正しいものは？', c: ['生育旺盛でそろいが良いが、採った種子からは同じ形質が出にくい', '自家採種すれば親とまったく同じものができる', 'すべて遺伝子組換え作物である', '病気に絶対かからない'], e: '両親より優れた性質を示す雑種強勢（ヘテロシス）を利用している。次の世代では形質が分離する。' },
  { id: 'v53', f: 'veg', q: 'ダイコンの根が二股などに分かれる「岐根（またね）」の主な原因は？', c: ['土中の石や未熟な堆肥', '窒素不足', '低温', '日照不足'], e: '根の先端が障害物にあたると分かれる。深く耕し、完熟堆肥を使う。' },
  { id: 'v54', f: 'veg', q: 'ホウレンソウは日長反応でいうと何植物？', c: ['長日植物', '短日植物', '中性植物', '低温植物'], e: '春〜夏の長日で抽だいしやすい。春まきには抽だいしにくい品種を選ぶ。' },
  { id: 'v55', f: 'veg', q: 'カボチャの人工受粉で、雌花の見分け方として正しいものは？', c: ['花のつけ根に小さな果実（子房）がある', '花びらの数が多い', '雄花より必ず大きい', 'つるの先端にしか咲かない'], e: 'カボチャは雌雄異花。晴れた日の朝のうちに、雄花の花粉を雌花の柱頭につける。' },
  { id: 'v56', f: 'veg', q: 'トマトの茎を支柱やひもに結びつけて支える作業は？', c: ['誘引', '摘心', '芽かき', '摘果'], e: '茎が太っても締めつけないよう、8の字にゆるく結ぶ。' },
  { id: 'v57', f: 'veg', q: '収穫した野菜の温度をすばやく下げて、鮮度を保つことを何という？', c: ['予冷', '追熟', '催芽', '順化'], e: '収穫後も野菜は呼吸を続けるため、温度を下げて呼吸を抑え、品質低下を防ぐ。' },
  { id: 'v58', f: 'veg', q: 'シソ（大葉）は何科の野菜？', c: ['シソ科', 'セリ科', 'キク科', 'ミカン科'], e: 'シソ科は茎の断面が四角い。バジルやミントも同じ仲間。' },
  { id: 'v59', f: 'veg', q: 'スイカやメロンの接ぎ木で、つる割病などを防ぐために使われる台木は？', c: ['ユウガオ・カボチャ', 'トマト', 'ナス', 'キュウリ'], e: 'スイカではユウガオ台、メロンではカボチャやメロン共台などが使われる。' },

  // ----- 草花（追加） -----
  { id: 'f39', f: 'flower', q: 'ガーベラは何科の草花？', c: ['キク科', 'バラ科', 'ナデシコ科', 'ユリ科'], e: 'キク科。切り花として人気で、花の色が豊富。' },
  { id: 'f40', f: 'flower', q: 'スイートピーは何科の草花？', c: ['マメ科', 'ナデシコ科', 'キク科', 'スミレ科'], e: 'マメ科。チョウのような形の花（蝶形花）を咲かせる。' },
  { id: 'f41', f: 'flower', q: '茎頂（成長点）を無菌的に培養して、ウイルスフリーのクローン苗を大量に増やす技術は？', c: ['茎頂培養（メリクロン）', '挿し木', '実生', '株分け'], e: 'シンビジウムなどのランやカーネーションで実用化されている。' },
  { id: 'f42', f: 'flower', q: 'ハボタンは何科の植物？', c: ['アブラナ科', 'キク科', 'ナデシコ科', 'スミレ科'], e: 'キャベツの仲間で、冬の低温にあうと葉が色づく。' },
  { id: 'f43', f: 'flower', q: 'プリムラ・ポリアンサは何科の草花？', c: ['サクラソウ科', 'キク科', 'スミレ科', 'シソ科'], e: 'シクラメンも同じサクラソウ科。冬〜春の鉢花として人気。' },
  { id: 'f44', f: 'flower', q: '苗を、それまでより大きな鉢に植えかえることを何という？', c: ['鉢替え', '鉢上げ', '間引き', '摘心'], e: '鉢上げは育苗箱などから最初に鉢へ植えること。根が鉢にまわったら鉢替えする。' },
  { id: 'f45', f: 'flower', q: 'ヒヤシンスやクロッカスを、土を使わず水だけで育てて開花させる方法は？', c: ['水栽培', '腰水', '挿し木', '株分け'], e: '球根に養分が蓄えられているため、肥料なしの水だけでも花を咲かせられる（ヒヤシンス用のガラス容器が有名）。肥料を溶かした培養液で野菜などを育てる「水耕栽培（養液栽培）」とは別もの。' },
  { id: 'f46', f: 'flower', q: '鉢を水を張った容器に入れ、鉢底から水を吸わせる方法は？', c: ['底面給水（腰水）', '頭上かん水', '葉水', '点滴かん水'], e: '細かい種子をまいた鉢でも、種子を流さずに水を与えられる。' },
  { id: 'f47', f: 'flower', q: '1本の茎に大きな花を1輪だけ咲かせるよう、側蕾を摘み取って仕立てるキクは？', c: ['輪ギク', 'スプレーギク', '小ギク', 'ポットマム'], e: 'スプレーギクは1本の茎に多くの花を咲かせる。' },
  { id: 'f48', f: 'flower', q: 'つぼみを摘み取って、残した花を大きく咲かせる作業は？', c: ['摘蕾', '摘心', '摘果', '花がら摘み'], e: '輪ギクの側蕾の除去などで行う。' },
  { id: 'f49', f: 'flower', q: 'アジサイの花色は土壌のpHで変わる。酸性土壌では一般に何色になる？', c: ['青色', '赤色', '白色', '黄色'], e: '酸性土ではアルミニウムが溶け出して吸収され、色素と結びついて青くなる。中性〜アルカリ性ではピンク系になる。' },
  { id: 'f50', f: 'flower', q: '日本で切り花の出荷量が最も多い品目は？', c: ['キク', 'バラ', 'カーネーション', 'ユリ'], e: 'キクは仏花・業務用などの需要が多く、電照栽培などで一年中出荷される。' },
  { id: 'f51', f: 'flower', q: '切り花を収穫するときの、花の開き具合（収穫のタイミング）を何という？', c: ['切り前', '切り戻し', '水揚げ', '前処理'], e: '品目や出荷先までの距離で適切な切り前が異なる。かたすぎるつぼみで切ると開花しないこともある。' },
  { id: 'f52', f: 'flower', q: 'ひる石を高温で焼いてつくる、保水性・保肥性の高い軽量な人工用土は？', c: ['バーミキュライト', 'パーライト', '鹿沼土', '赤玉土'], e: 'パーライトは真珠岩などを高温処理したもので、排水性・通気性を高める。' },
  { id: 'f53', f: 'flower', q: '関東ローム層の赤土を乾燥させ、粒の大きさでふるい分けた基本用土は？', c: ['赤玉土', '鹿沼土', '腐葉土', 'ピートモス'], e: '通気性・保水性・保肥性のバランスが良く、多くの草花の用土のベースになる。' },
  { id: 'f54', f: 'flower', q: 'ミズゴケなどが長い年月をかけて堆積・分解してできた、酸性の有機質用土は？', c: ['ピートモス', '腐葉土', 'バーク堆肥', 'くん炭'], e: '無調整のものは強い酸性。ブルーベリーの植え付けにも使われる。' },
  { id: 'f55', f: 'flower', q: 'もみ殻を蒸し焼きにしてつくる、アルカリ性で通気性の良い土壌改良材は？', c: ['もみ殻くん炭', '腐葉土', 'ピートモス', '苦土石灰'], e: '用土に混ぜると通気性・排水性が良くなる。' },
  { id: 'f56', f: 'flower', q: 'チューリップの花が終わった後、球根を太らせるために行うことは？', c: ['花首を摘み取り、葉は残して光合成させる', '葉もすべて刈り取る', 'すぐに水やりをやめて掘り上げる', '球根を逆さに植え直す'], e: '葉でつくられた養分が球根に送られる。葉が黄色くなったら掘り上げて乾燥させる。' },
  { id: 'f57', f: 'flower', q: '高温乾燥期に葉の裏で増え、葉がかすり状に白く抜ける、クモの仲間の害虫は？', c: ['ハダニ', 'アブラムシ', 'コナジラミ', 'アザミウマ'], e: '昆虫ではなくダニの仲間。葉裏への散水（葉水）で増殖を抑えられる。' },
  { id: 'f58', f: 'flower', q: '体長1〜2mmほどで花の中にもぐり、花弁に白いかすり状の傷をつける細長い害虫は？', c: ['アザミウマ（スリップス）', 'ハダニ', 'ナメクジ', 'カイガラムシ'], e: 'ウイルス病を媒介するものもいる。青色の粘着板で誘引して捕らえられる。' },

  // ----- 果樹（追加） -----
  { id: 'r40', f: 'fruit', q: 'クリ・クルミのように、硬い殻の中の種子を食べる果樹のグループは？', c: ['堅果類', '核果類', '仁果類', 'しょう果類'], e: 'ナッツ類ともいう。アーモンドも堅果類。' },
  { id: 'r41', f: 'fruit', q: 'ウメは何科の果樹？', c: ['バラ科', 'ミカン科', 'モクセイ科', 'ツバキ科'], e: '核果類。主産地は和歌山県で、「南高」が代表品種。' },
  { id: 'r42', f: 'fruit', q: 'イチジクで食べている部分は？', c: ['花のう（花托が肥大したもの）', '種子', '葉柄', '根'], e: '内側に小さな花がたくさん咲く隠頭花序。中のつぶつぶ一つ一つが本当の果実。' },
  { id: 'r43', f: 'fruit', q: 'ブドウなどで、雨による病気を防ぐためにビニールで覆って育てる栽培法は？', c: ['雨よけ栽培', '草生栽培', '清耕栽培', '養液栽培'], e: 'ブドウの晩腐病やべと病は雨で広がる。オウトウでは裂果防止にも使われる。' },
  { id: 'r44', f: 'fruit', q: '「デコポン」として出荷されるカンキツの品種名は？', c: ['不知火', '清見', 'ポンカン', 'せとか'], e: '「清見」×「ポンカン」の交配で育成された不知火のうち、糖度などの基準を満たしたものがデコポンとして出荷される。' },
  { id: 'r45', f: 'fruit', q: '袋をかけずに日光を十分に当てて育てた「ふじ」を何という？', c: ['サンふじ', '早生ふじ', '王林', 'つがる'], e: '外観はやや劣るが、糖度が高くなりやすい。' },
  { id: 'r46', f: 'fruit', q: '果実の収穫後、消耗した樹の回復のために施す肥料を何という？', c: ['礼肥（お礼肥）', '元肥', '穂肥', '芽出し肥'], e: '樹勢を回復させ、翌年の花芽の充実をはかる。' },
  { id: 'r47', f: 'fruit', q: '落葉果樹の休眠期（冬）に薬剤を散布する主な目的は？', c: ['越冬している病原菌や害虫を減らす', '果実を甘くする', '花芽を増やす', '葉を早く落とす'], e: '石灰硫黄合剤やマシン油乳剤などが使われる。' },
  { id: 'r48', f: 'fruit', q: '枝や幹に固着して汁を吸い、ろう物質の殻で薬剤がかかりにくい果樹の害虫は？', c: ['カイガラムシ', 'アブラムシ', 'ハダニ', 'カメムシ'], e: '冬に歯ブラシなどでこすり落としたり、休眠期にマシン油乳剤を散布したりする。' },
  { id: 'r49', f: 'fruit', q: 'ブドウの剪定で、結果母枝を1〜2芽残して短く切る方法は？', c: ['短梢剪定', '長梢剪定', '間引き剪定', '夏季剪定'], e: '樹形が単純で作業を省力化しやすい。長梢剪定は枝を長く残す方法。' },
  { id: 'r50', f: 'fruit', q: 'モモやスモモの葉に小さな斑点ができ、やがて穴があく細菌による病気は？', c: ['せん孔細菌病', '縮葉病', '黒星病', 'うどんこ病'], e: '春先の風雨で広がる。防風対策も効果的。' },
  { id: 'r51', f: 'fruit', q: '枝や幹の樹皮を幅数mmで一周はぎ取り、葉でつくられた養分を果実にためる技術は？', c: ['環状剥皮', '切り返し剪定', '芽かき', '誘引'], e: 'ブドウの着色や糖度の向上などに使われる。はぎすぎると樹が弱るので注意。' },
  { id: 'r52', f: 'fruit', q: '自家不和合性の果樹園で、花粉の供給源として植える木を何という？', c: ['受粉樹', '台木', '中間台木', '防風樹'], e: '主力品種と開花期が重なり、受精できる組み合わせの品種を選ぶ。' },
  { id: 'r53', f: 'fruit', q: 'カンキツの果皮に含まれる、さわやかな香りのもとになる成分は？', c: ['リモネン', 'リコピン', 'カプサイシン', 'ソラニン'], e: '果皮の油胞に多く含まれる。' },
  { id: 'r54', f: 'fruit', q: '果樹で、花芽がついて果実をつける枝を何という？', c: ['結果枝', '徒長枝', 'ひこばえ', '台芽'], e: '結果枝が出る前年の枝を結果母枝という。' },
  { id: 'r55', f: 'fruit', q: 'オウトウ（サクランボ）の代表品種で、山形県で多く栽培されているのは？', c: ['佐藤錦', 'あまおう', '幸水', '富有'], e: '「ナポレオン」×「黄玉」の交配で育成された。あまおうはイチゴ、幸水はナシ、富有はカキの品種。' },
  { id: 'r56', f: 'fruit', q: 'モモの生産量が日本一の都道府県は？', c: ['山梨県', '青森県', '愛媛県', '鹿児島県'], e: '山梨県・福島県・長野県などが主産地。' },
  { id: 'r57', f: 'fruit', q: 'リンゴの生産量が日本一の都道府県は？', c: ['青森県', '長野県', '山形県', '岩手県'], e: '全国の生産量の約6割を青森県が占める。' },
  { id: 'r58', f: 'fruit', q: 'ブドウの生産量が日本一の都道府県は？', c: ['山梨県', '長野県', '岡山県', '山形県'], e: '山梨県・長野県・岡山県などが主産地。' },
  { id: 'r59', f: 'fruit', q: 'ウンシュウミカンの生産量が日本一の都道府県は？', c: ['和歌山県', '愛媛県', '静岡県', '熊本県'], e: '和歌山県・愛媛県・静岡県などが主産地。' },

  // ----- 作物（追加） -----
  { id: 'c41', f: 'crop', q: '種もみを約60℃の湯に10分ほど浸して、種子伝染する病原菌を減らす方法は？', c: ['温湯消毒', '塩水選', '浸種', '催芽'], e: '農薬を使わない種子消毒で、有機栽培などでも利用される。' },
  { id: 'c42', f: 'crop', q: 'イネの花が多く開花する時間帯は？', c: ['晴れた日の午前中', '夕方', '真夜中', '一日中ずっと開いている'], e: '1つの花は開いてから1〜2時間ほどで閉じる。' },
  { id: 'c43', f: 'crop', q: 'イネの収量は「穂数×1穂籾数×（　）×千粒重」で表される。（　）に入るのは？', c: ['登熟歩合', '分げつ数', '草丈', '葉齢'], e: 'これを「収量構成要素」という。' },
  { id: 'c44', f: 'crop', q: '田植えをせず、田に直接種もみをまく栽培方法は？', c: ['直播栽培', '移植栽培', '二期作', '不耕起栽培'], e: '育苗や田植えの労力を省ける。鉄コーティング種子などが使われる。' },
  { id: 'c45', f: 'crop', q: '田植え直後のやわらかいイネの苗を食害する、南米原産の大型の巻貝は？', c: ['スクミリンゴガイ', 'モノアラガイ', 'カタツムリ', 'シジミ'], e: 'ジャンボタニシとも呼ばれ、ピンク色の卵塊を産む。浅水管理で被害を減らす。' },
  { id: 'c46', f: 'crop', q: 'イネの籾を吸汁し、米粒に黒い点ができる「斑点米」の原因となる害虫は？', c: ['カメムシ類', 'ウンカ類', 'イネミズゾウムシ', 'スクミリンゴガイ'], e: '斑点米が混じると米の等級が下がる。出穂前の畦畔の草刈りで発生源を減らす。' },
  { id: 'c47', f: 'crop', q: 'ダイズの受粉の方式は？', c: ['自家受粉（自殖性）', '他家受粉', '風媒受粉', '昆虫による受粉が必須'], e: '花が開く前に受粉が終わることも多い。' },
  { id: 'c48', f: 'crop', q: '収穫が遅れたダイズの莢がはじけて、子実がこぼれ落ちることを何という？', c: ['裂莢', '倒伏', '登熟', '分げつ'], e: '収穫適期を逃さないことが大切。' },
  { id: 'c49', f: 'crop', q: '植え付け前のジャガイモの種いもを光に当てて、丈夫な芽を出させる処理は？', c: ['浴光催芽', '春化処理', '温湯消毒', '順化'], e: '太く短い芽をそろえることで、萌芽がそろい初期生育が良くなる。' },
  { id: 'c50', f: 'crop', q: 'ジャガイモの種いもを切って植えるとき、切り口の腐敗を防ぐために行うことは？', c: ['切り口を乾かす', '切り口を水でぬらす', '種いもを冷凍する', '芽をすべて取り除く'], e: '1片に芽が残るように切り分け、切り口を乾かしてから植える。' },
  { id: 'c51', f: 'crop', q: 'サツマイモのつるの節から出た根を切るため、つるを持ち上げて裏返す作業は？', c: ['つる返し', '誘引', '摘心', '土寄せ'], e: '節から出た根に養分が分散するのを防ぐ。近年の品種では行わないことも多い。' },
  { id: 'c52', f: 'crop', q: '収穫したサツマイモを高温多湿（約30℃・湿度90%以上）に数日おき、傷口にコルク層をつくらせて貯蔵性を高める処理は？', c: ['キュアリング', '追熟', '予冷', '脱渋'], e: '傷口からの病原菌の侵入を防ぎ、長期貯蔵できるようにする。' },
  { id: 'c53', f: 'crop', q: 'サツマイモの貯蔵に適した温度は？', c: ['13〜15℃程度', '0〜2℃', '25〜30℃', 'マイナス5℃'], e: '低温に弱く、10℃以下では低温障害で腐りやすい。' },
  { id: 'c54', f: 'crop', q: 'スイートコーンに別の品種の花粉がかかり、粒の色や甘さが変わってしまう現象は？', c: ['キセニア', '単為結果', '雑種強勢', '隔年結果'], e: '品種の異なるトウモロコシは離して植えるか、開花時期をずらす。' },
  { id: 'c55', f: 'crop', q: '開花期の雨で多発し、穂が赤っぽくなってカビ毒をつくるムギの病気は？', c: ['赤かび病', 'うどんこ病', 'さび病', 'いもち病'], e: '人や家畜に有害なカビ毒を生成するため、開花期の防除が重要。' },
  { id: 'c56', f: 'crop', q: '収穫せずにそのまま土にすき込み、肥料や土壌改良に利用する作物を何という？', c: ['緑肥作物', '飼料作物', '工芸作物', '園芸作物'], e: 'レンゲ・ヘアリーベッチ・ソルガムなど。マメ科の緑肥は窒素も補給できる。' },
  { id: 'c57', f: 'crop', q: 'トウモロコシなどを茎や葉ごと細かく刻み、乳酸発酵させてつくる牛の飼料は？', c: ['サイレージ', '乾草', '稲わら', '配合飼料'], e: '密封して発酵させることで長期保存できる。' },
  { id: 'c58', f: 'crop', q: '土の「三相」とは、固相・液相と何？', c: ['気相', '水相', '有機相', '鉱物相'], e: '作物の根の生育には、水分と空気のバランスがよい土が適している。' },
  { id: 'c59', f: 'crop', q: '土の粒子が集まって小さな塊をつくり、通気性・保水性・排水性にすぐれた土の構造は？', c: ['団粒構造', '単粒構造', '層状構造', '柱状構造'], e: '堆肥などの有機物や土壌微生物のはたらきでつくられる。' },
  { id: 'c60', f: 'crop', q: '雨の多い日本の気候で、畑の土壌が傾きやすいのは？', c: ['酸性', 'アルカリ性', '中性から変わらない', '塩分が多い状態'], e: '雨でカルシウムなどの塩基が流され、酸性化しやすい。石灰資材で矯正する。' },
  { id: 'c61', f: 'crop', q: '下の古い葉から黄色くなる、作物の代表的な欠乏症は？', c: ['窒素欠乏', 'カルシウム欠乏', '鉄欠乏', 'ホウ素欠乏'], e: '窒素は植物体内を移動しやすいので、不足すると古い葉から症状が出る。カルシウムや鉄の欠乏は新しい葉に出やすい。' },
  // ================= 共通（農業の基礎） =================
  { id: 'b01', f: 'basic', q: '種子の発芽に必要な3つの条件は？', c: ['水・温度・酸素', '水・光・肥料', '光・温度・肥料', '水・酸素・肥料'], e: '光は多くの種子では必要ない（好光性・嫌光性種子は光の影響を受ける）。発芽に使う養分は種子の中に蓄えられている。' },
  { id: 'b02', f: 'basic', q: '種子の中で、将来、芽や根など植物の体になる部分は？', c: ['胚', '胚乳', '種皮', 'へそ'], e: '胚は幼芽・胚軸・幼根・子葉からできている。' },
  { id: 'b03', f: 'basic', q: 'イネやトウモロコシのように、発芽のための養分を胚乳に蓄えている種子を何という？', c: ['有胚乳種子', '無胚乳種子', '好光性種子', '硬実種子'], e: 'マメ類やアブラナ科などは子葉に養分を蓄える無胚乳種子。' },
  { id: 'b04', f: 'basic', q: 'ダイズやインゲンマメの種子で、発芽のための養分を蓄えている部分は？', c: ['子葉', '胚乳', '種皮', '幼根'], e: 'マメ類は胚乳がなく、厚い子葉に養分を蓄える（無胚乳種子）。' },
  { id: 'b05', f: 'basic', q: '種皮が硬く水を吸いにくいため、発芽しにくい種子を何という？', c: ['硬実種子', '好光性種子', '有胚乳種子', '不稔種子'], e: 'アサガオ・オクラ・スイートピーなど。種皮に傷をつけたり、一晩水に浸けたりしてからまく。' },
  { id: 'b06', f: 'basic', q: 'まいた種子のうち、発芽した種子の割合を何という？', c: ['発芽率', '発芽勢', '結実率', '登熟歩合'], e: '発芽勢は発芽の初期（一定期間内）に発芽した割合で、発芽のそろいや勢いを表す。' },
  { id: 'b07', f: 'basic', q: '発芽の条件がそろっていても、種子がすぐには発芽しない状態を何という？', c: ['休眠', '抽だい', '春化', '徒長'], e: '休眠には、収穫前の穂発芽を防ぐなどの役割がある。' },
  { id: 'b08', f: 'basic', q: '種子を長持ちさせる保存条件は？', c: ['低温・乾燥', '高温・多湿', '高温・乾燥', '低温・多湿'], e: '種子の呼吸を抑えて寿命を延ばす。乾燥剤といっしょに密閉し、冷蔵庫で保存するとよい。' },
  { id: 'b09', f: 'basic', q: '一般的な覆土の厚さの目安は？', c: ['種子の直径の2〜3倍程度', '種子の直径の10倍以上', '種子の直径の半分', '覆土はしない'], e: '好光性種子はごく薄く（またはしない）、嫌光性種子はしっかり覆土する。' },
  { id: 'b10', f: 'basic', q: '畑にすじ状の溝をつけて、種子を連続してまく方法は？', c: ['条播（すじまき）', '点播（点まき）', '散播（ばらまき）', '移植'], e: 'ホウレンソウ・ニンジン・コマツナなどで行う。間引きや中耕がしやすい。' },
  { id: 'b11', f: 'basic', q: '一定の間隔で、1か所に数粒ずつ種子をまく方法は？', c: ['点播（点まき）', '条播（すじまき）', '散播（ばらまき）', '移植'], e: 'ダイコン・トウモロコシ・マメ類など、株が大きくなる作物で行う。' },
  { id: 'b12', f: 'basic', q: '床面全体に種子を均一にまく方法は？', c: ['散播（ばらまき）', '条播（すじまき）', '点播（点まき）', '移植'], e: '細かい種子の育苗箱へのまきつけや、ベビーリーフなどで行う。' },
  { id: 'b13', f: 'basic', q: '育てた苗を、最終的に栽培する場所（畑やハウス）に植え付けることを何という？', c: ['定植', '仮植', '鉢上げ', '播種'], e: '途中で一時的に植えかえることを仮植という。' },
  { id: 'b14', f: 'basic', q: '日光不足や、水分・窒素・温度が多すぎることで、茎が細く間のびすることを何という？', c: ['徒長', '抽だい', '分げつ', '順化'], e: '徒長した苗は倒れやすく、病気にもかかりやすい。' },
  { id: 'b15', f: 'basic', q: '土の中の病原菌や害虫、雑草の種子を、熱や薬剤で減らす処理を何という？', c: ['土壌消毒', '中耕', '鎮圧', '耕起'], e: '夏の強い日差しを利用する太陽熱消毒や、蒸気消毒などがある。' },
  { id: 'b16', f: 'basic', q: '光合成で、植物が材料として取り入れるものは？', c: ['二酸化炭素と水', '酸素と水', '二酸化炭素と酸素', '窒素と水'], e: '光のエネルギーを使って二酸化炭素と水から糖（デンプン）をつくり、酸素を出す。' },
  { id: 'b17', f: 'basic', q: '光合成が行われる、細胞内の緑色の粒は？', c: ['葉緑体', 'ミトコンドリア', '核', '液胞'], e: '葉緑体には光を吸収する緑色の色素（クロロフィル）が含まれている。' },
  { id: 'b18', f: 'basic', q: '呼吸が行われる細胞内の小器官は？', c: ['ミトコンドリア', '葉緑体', '細胞壁', '液胞'], e: '糖を分解して、生きるためのエネルギーを取り出す。呼吸は昼も夜も行われている。' },
  { id: 'b19', f: 'basic', q: '光合成量と呼吸量がつり合い、見かけの光合成がゼロになる光の強さを何という？', c: ['光補償点', '光飽和点', '臨界日長', '積算温度'], e: 'これより暗いと植物は成長できない。日陰に強い陰生植物は光補償点が低い。' },
  { id: 'b20', f: 'basic', q: 'それ以上光を強くしても、光合成量が増えなくなる光の強さを何という？', c: ['光飽和点', '光補償点', '臨界日長', '積算温度'], e: 'トマトなど光飽和点の高い作物は、強い光を好む。' },
  { id: 'b21', f: 'basic', q: '夜温が高すぎると、作物の生育や品質が悪くなりやすいのはなぜ？', c: ['呼吸で消費される糖が増えるから', '光合成が増えすぎるから', '根が水を吸わなくなるから', '気孔が開かなくなるから'], e: '昼夜の温度差が大きいと糖がたまりやすく、果実の糖度が高くなりやすい。' },
  { id: 'b22', f: 'basic', q: '植物の体内の水が、主に葉の気孔から水蒸気となって出ていくことを何という？', c: ['蒸散', '呼吸', '光合成', '吸水'], e: '蒸散は根からの水や養分の吸い上げを助け、葉の温度が上がりすぎるのを防ぐ。' },
  { id: 'b23', f: 'basic', q: '葉の表皮にあり、二酸化炭素・酸素・水蒸気が出入りする小さなすき間は？', c: ['気孔', '皮目', '道管', '師管'], e: '2つの孔辺細胞で開け閉めされる。多くの植物では葉の裏側に多い。' },
  { id: 'b24', f: 'basic', q: '根から吸収した水や養分が通る管は？', c: ['道管', '師管', '気孔', '形成層'], e: '葉でつくられた糖などは師管を通る。道管と師管が集まった部分を維管束という。' },
  { id: 'b25', f: 'basic', q: '葉でつくられた糖などの養分が、体の各部へ運ばれる管は？', c: ['師管', '道管', '気孔', '皮目'], e: '環状剥皮は、師管を含む樹皮をはいで養分の移動を止める技術。' },
  { id: 'b26', f: 'basic', q: '果実の成熟や落葉を促進する、気体の植物ホルモンは？', c: ['エチレン', 'ジベレリン', 'オーキシン', 'サイトカイニン'], e: 'リンゴから出るエチレンで、いっしょに置いた果実の追熟が進む。' },
  { id: 'b27', f: 'basic', q: '細胞分裂を促し、わき芽の生長を促進する植物ホルモンは？', c: ['サイトカイニン', 'エチレン', 'アブシシン酸', 'ジベレリン'], e: '組織培養でも、オーキシンとの組み合わせで芽や根の分化を調節する。' },
  { id: 'b28', f: 'basic', q: '乾燥したときに気孔を閉じさせたり、種子や芽の休眠を保ったりする植物ホルモンは？', c: ['アブシシン酸', 'オーキシン', 'サイトカイニン', 'ジベレリン'], e: 'ストレスに対応するホルモンとして知られる。' },
  { id: 'b29', f: 'basic', q: '挿し木の発根促進剤に使われる植物ホルモンの系統は？', c: ['オーキシン', 'エチレン', 'アブシシン酸', 'サイトカイニン'], e: 'オーキシンには根の形成を促すはたらきがある。' },
  { id: 'b30', f: 'basic', q: '植物の茎が、光の来る方向に曲がって伸びる性質を何という？', c: ['屈光性（光屈性）', '重力屈性', '接触屈性', '頂芽優勢'], e: '光の当たらない側にオーキシンが多く集まり、そちら側がよく伸びるため。' },
  { id: 'b31', f: 'basic', q: '昼の長さ（夜の長さ）によって花芽の形成が左右される性質を何という？', c: ['光周性', '屈光性', '春化', '休眠'], e: '短日植物・長日植物・中性植物に分けられる。実際には、連続した暗期の長さが重要。' },
  { id: 'b32', f: 'basic', q: '種まきや植え付けの前に、あらかじめ施しておく肥料を何という？', c: ['元肥（基肥）', '追肥', '礼肥', '穂肥'], e: '生育初期に必要な養分を土に入れておく。' },
  { id: 'b33', f: 'basic', q: '作物の生育の途中で、不足する養分を補うために施す肥料を何という？', c: ['追肥', '元肥', '礼肥', '土壌改良材'], e: '生育の様子を見ながら、適した時期に適量を施す。' },
  { id: 'b34', f: 'basic', q: '化成肥料の袋に「8-8-8」とある。この数字が表すものは？', c: ['窒素・リン酸・カリの含有率（%）', '肥料の重さ（kg）', '1袋で施せる面積（a）', '肥料の有効期限（月）'], e: 'N（窒素）-P（リン酸）-K（カリ）の順に、成分の割合（%）を表している。' },
  { id: 'b35', f: 'basic', q: '「8-8-8」の化成肥料20kgに含まれる窒素の量は？', c: ['1.6kg', '8kg', '0.8kg', '16kg'], e: '20kg × 8% ＝ 1.6kg。リン酸とカリもそれぞれ1.6kgずつ含まれる。' },
  { id: 'b36', f: 'basic', q: '油かすや鶏ふん・魚かすのように、動植物に由来する肥料を何という？', c: ['有機質肥料', '化学肥料', '被覆肥料', '単肥'], e: '土の中の微生物に分解されてから効くため、効き目はゆっくり。' },
  { id: 'b37', f: 'basic', q: '効き目がゆっくりと長く続くようにつくられた肥料を何という？', c: ['緩効性肥料', '速効性肥料', '液体肥料', '単肥'], e: '肥料を樹脂で包んだ被覆肥料（コーティング肥料）など。施肥の回数を減らせる。' },
  { id: 'b38', f: 'basic', q: '窒素・リン酸・カリのうち、1つの成分だけを含む肥料を何という？', c: ['単肥', '複合肥料', '配合肥料', '有機質肥料'], e: '硫安（窒素）・過リン酸石灰（リン酸）・塩化カリ（カリ）など。' },
  { id: 'b39', f: 'basic', q: 'わらやおがくずなど、炭素の割合（C/N比）が高い未熟な有機物を土に入れたとき、作物が窒素不足になる現象は？', c: ['窒素飢餓', '肥料やけ', '塩類集積', '連作障害'], e: '微生物が有機物を分解するときに土の中の窒素を使ってしまうため。堆肥は十分に熟成させてから使う。' },
  { id: 'b40', f: 'basic', q: '土の中の肥料分（塩類）の濃さの目安として測る値は？', c: ['EC（電気伝導度）', 'pH', 'C/N比', '糖度（Brix）'], e: 'ECが高すぎると根が傷む。雨の当たらないハウスでは塩類集積に注意する。' },
  { id: 'b41', f: 'basic', q: '肥料を一度に多く施しすぎて、根が傷みしおれたり枯れたりすることを何という？', c: ['肥料やけ（濃度障害）', '窒素飢餓', '生理落果', '連作障害'], e: '肥料は根に直接触れないように施し、分けて施す（分施）ことも大切。' },
  { id: 'b42', f: 'basic', q: '植物の必須元素のうち、鉄・マンガン・ホウ素などのように、ごく少量でよいものを何という？', c: ['微量要素', '多量要素', '三要素', '有機要素'], e: '必要な量は少ないが、不足すると生育障害（欠乏症）が出る。' },
  { id: 'b43', f: 'basic', q: '土壌のpHが6.0のとき、その土壌は？', c: ['弱酸性', '中性', '弱アルカリ性', '強アルカリ性'], e: 'pH7が中性。多くの作物はpH6.0〜6.5程度の弱酸性の土を好む。' },
  { id: 'b44', f: 'basic', q: '天敵・抵抗性品種・防虫ネット・農薬などを組み合わせ、環境への負荷を減らしながら病害虫を防ぐ考え方は？', c: ['IPM（総合的病害虫・雑草管理）', 'GAP', 'HACCP', 'JAS'], e: 'GAPは農業生産工程管理、HACCPは食品の衛生管理の手法、JASは日本農林規格。' },
  { id: 'b45', f: 'basic', q: '農薬を1000倍に薄めて散布液を10Lつくるとき、必要な農薬の量は？', c: ['10mL', '100mL', '1mL', '1L'], e: '10L＝10000mL。10000mL ÷ 1000 ＝ 10mL。' },
  { id: 'b46', f: 'basic', q: '同じ系統の農薬を使い続けることで、害虫や病原菌に薬が効きにくくなることを何という？', c: ['薬剤抵抗性', '薬害', '残留農薬', '連作障害'], e: '作用の異なる農薬をローテーションで使うことで防ぐ。' },
  { id: 'b47', f: 'basic', q: '農薬ラベルの「収穫7日前まで」という表示の意味は？', c: ['収穫日の7日前までに散布を終える', '収穫後7日以内に散布する', '7日ごとに散布する', '7日間だけ効果がある'], e: '農薬取締法にもとづく使用基準。使用回数・希釈倍数も必ず守る。' },
  { id: 'b48', f: 'basic', q: '植物の病気の原因として最も多い、いもち病やうどんこ病などを起こす病原体は？', c: ['糸状菌（カビ）', '細菌', 'ウイルス', '線虫'], e: '青枯病・軟腐病は細菌、モザイク病はウイルスによる病気。' },
  { id: 'b49', f: 'basic', q: 'トラクターに取り付け、爪を回転させて土を耕し細かく砕く作業機は？', c: ['ロータリ', 'プラウ', 'ブロードキャスタ', 'マニュアスプレッダ'], e: 'プラウは土を反転させて耕す作業機。ブロードキャスタは肥料、マニュアスプレッダは堆肥を散布する。' },
  { id: 'b50', f: 'basic', q: '晴れて風のない春の夜に、放射冷却で気温が下がり、新芽や花が被害を受ける気象災害は？', c: ['晩霜害（遅霜）', '干害', '冷害', '風害'], e: '果樹園では防霜ファンを回して、上空の暖かい空気を地表に送り込む。' },
  { id: 'b51', f: 'basic', q: '毎日の平均気温を合計した値で、作物の生育時期の予測などに使うものは？', c: ['積算温度', '日較差', '光補償点', '年平均気温'], e: 'イネの浸種（積算約100℃）など、栽培管理の目安に使われる。' },
  { id: 'b52', f: 'basic', q: '夏の低温や日照不足で作物の生育が悪くなり、収量が減る気象災害は？', c: ['冷害', '晩霜害', '干害', '塩害'], e: 'イネでは穂ができる時期の低温で、花粉ができず不稔になりやすい。深水管理で幼穂を守る。' },
  { id: 'b53', f: 'basic', q: '食品安全・環境保全・労働安全などに取り組む「農業生産工程管理」の略称は？', c: ['GAP', 'IPM', 'HACCP', 'JAS'], e: 'JGAP・ASIAGAP・GLOBALG.A.P.などの認証があり、取得に取り組む農業高校も増えている。' },
  { id: 'b54', f: 'basic', q: '植物の細胞にあり、動物の細胞にはないものは？', c: ['細胞壁と葉緑体', '核とミトコンドリア', '細胞膜と核', 'ミトコンドリアと細胞膜'], e: '細胞壁は植物の体を支える。液胞が大きく発達するのも植物細胞の特徴。' },
  { id: 'b55', f: 'basic', q: '接ぎ木で、台木と穂木の何という部分を密着させると活着しやすい？', c: ['形成層', '道管', '表皮', '髄'], e: '形成層は細胞分裂が盛んな部分で、ここ同士がつながって一体になる。' },
  // ================= 食品製造 =================
  { id: 'p01', f: 'food', q: '五大栄養素のうち、主にエネルギー源となり、米やいもに多く含まれるものは？', c: ['炭水化物', 'たんぱく質', 'ビタミン', 'ミネラル'], e: '炭水化物・脂質・たんぱく質を三大栄養素といい、エネルギー源となる。' },
  { id: 'p02', f: 'food', q: '筋肉や血液など体をつくる材料となり、肉・魚・卵・大豆に多く含まれる栄養素は？', c: ['たんぱく質', '炭水化物', '脂質', 'ビタミン'], e: 'たんぱく質は多数のアミノ酸がつながってできている。' },
  { id: 'p03', f: 'food', q: '1gあたりのエネルギーが最も大きい栄養素は？', c: ['脂質', '炭水化物', 'たんぱく質', 'ビタミン'], e: '脂質は1gあたり約9kcal、炭水化物とたんぱく質は約4kcal。ビタミンやミネラルはエネルギー源にならない。' },
  { id: 'p04', f: 'food', q: 'リンゴやバナナを切って置くと、切り口が茶色くなる現象は？', c: ['酵素的褐変', 'メイラード反応', 'カラメル化', '糊化'], e: 'ポリフェノールが酵素で酸化されて起こる。食塩水やレモン汁につけると防げる。' },
  { id: 'p05', f: 'food', q: '糖とアミノ酸を加熱したときに起こり、パンの焼き色やしょうゆの色のもとになる反応は？', c: ['メイラード反応（アミノカルボニル反応）', '酵素的褐変', '乳酸発酵', 'ゲル化'], e: '色だけでなく、香ばしい香りも生まれる。' },
  { id: 'p06', f: 'food', q: '油脂が空気中の酸素などで劣化し、いやなにおいや有害物質を生じることを何という？', c: ['酸敗（酸化）', '発酵', '糊化', '熟成'], e: '光や高温で進みやすい。遮光・低温で保存したり、酸化防止剤（ビタミンEなど）を使ったりして防ぐ。' },
  { id: 'p07', f: 'food', q: '生のデンプンに水を加えて加熱し、やわらかく消化しやすい状態にすることを何という？', c: ['糊化（α化）', '老化（β化）', '褐変', '乳化'], e: '炊いたご飯が冷えて硬くなるのは、デンプンの老化（β化）による。' },
  { id: 'p08', f: 'food', q: '水と油のように混ざり合わないものを、細かく分散させて混ぜ合わせることを何という？', c: ['乳化', '糊化', '凝固', '分離'], e: 'マヨネーズは、卵黄のレシチンが乳化剤となって油と酢が混ざっている。' },
  { id: 'p09', f: 'food', q: '食品の腐敗や発酵にかかわる微生物の3つのグループは？', c: ['細菌・カビ・酵母', 'ウイルス・細菌・寄生虫', 'カビ・ウイルス・線虫', '酵母・ウイルス・原虫'], e: '微生物が増えるには、水分・温度・栄養が必要。' },
  { id: 'p10', f: 'food', q: '食品中の水のうち、微生物が利用できる水（自由水）の割合を表す指標は？', c: ['水分活性', '水分含量', '糖度', 'pH'], e: '0〜1の値で表す。乾燥・塩蔵・糖蔵は水分活性を下げて微生物の増殖を抑える保存法。' },
  { id: 'p11', f: 'food', q: '食塩を使って水分活性を下げ、保存性を高める方法は？', c: ['塩蔵', '糖蔵', '燻煙', '冷凍'], e: '漬物・塩辛・塩ざけなど。' },
  { id: 'p12', f: 'food', q: 'ジャムのように、砂糖を多く加えて保存性を高める方法は？', c: ['糖蔵', '塩蔵', '酢漬け', '燻煙'], e: '砂糖が水分と結びつき、微生物が利用できる水を減らす。' },
  { id: 'p13', f: 'food', q: '木材をいぶした煙で、食品に風味と保存性を与える方法は？', c: ['燻煙（くん製）', '糖蔵', '塩蔵', '冷凍'], e: '煙の成分の殺菌・抗酸化作用と、表面の乾燥によって保存性が高まる。' },
  { id: 'p14', f: 'food', q: '食品を凍らせてから真空中で水分を昇華させて乾燥させる方法は？', c: ['凍結乾燥（フリーズドライ）', '噴霧乾燥', '天日乾燥', '熱風乾燥'], e: 'インスタントみそ汁など。風味や形が保たれ、水で戻しやすい。' },
  { id: 'p15', f: 'food', q: '缶詰の製造で、密封する前に容器内の空気を抜く工程は？', c: ['脱気', '殺菌', '巻締め', '冷却'], e: '中身の酸化を防ぎ、加熱時の容器の膨張を抑える。' },
  { id: 'p16', f: 'food', q: '缶詰の密封や殺菌が不十分なときに増殖し、強い神経毒をつくる、酸素を嫌う細菌は？', c: ['ボツリヌス菌', '乳酸菌', '納豆菌', '酢酸菌'], e: '酸素のない環境で増え、芽胞は熱に強い。' },
  { id: 'p17', f: 'food', q: '袋などに密封した食品を、120℃前後の高温高圧で殺菌した食品は？', c: ['レトルト食品', '冷凍食品', '乾燥食品', '塩蔵食品'], e: 'レトルトは加圧加熱殺菌釜のこと。常温で長期保存できる。' },
  { id: 'p18', f: 'food', q: '加熱殺菌後の食品を急速に冷やす理由は？', c: ['微生物が増えやすい温度帯を早く通過させるため', '色を濃くするため', '重さを増やすため', '味を薄めるため'], e: '多くの細菌は20〜50℃前後でよく増える。' },
  { id: 'p19', f: 'food', q: '漬物で野菜に食塩をまぶすと水分が出てくるのは、何の作用によるもの？', c: ['浸透圧', '表面張力', '毛細管現象', '遠心力'], e: '塩分濃度の高い外側へ、細胞の中の水が引き出される。重しは野菜を漬け液に浸し、水の上がりを早めるために使う。' },
  { id: 'p20', f: 'food', q: '牛乳の「低温保持殺菌」の条件は？', c: ['63〜65℃で30分間', '120〜150℃で1〜3秒', '100℃で10分間', '40℃で2時間'], e: '日本の牛乳の多くは、120〜150℃で1〜3秒の超高温瞬間殺菌（UHT）。' },
  { id: 'p21', f: 'food', q: '牛乳の脂肪球を細かく砕いて均一にし、クリーム層ができるのを防ぐ処理は？', c: ['均質化（ホモジナイズ）', '殺菌', '分離', '発酵'], e: '均質化しないノンホモ牛乳は、上部にクリーム層ができる。' },
  { id: 'p22', f: 'food', q: '牛乳を乳酸菌で発酵させてつくる食品は？', c: ['ヨーグルト', 'バター', '生クリーム', 'スキムミルク'], e: '乳酸菌がつくる乳酸によって、乳たんぱく質（カゼイン）が固まる。' },
  { id: 'p23', f: 'food', q: 'チーズづくりで、牛乳を固める（凝乳させる）ために加える酵素は？', c: ['レンネット（キモシン）', 'アミラーゼ', 'ペクチン', 'にがり'], e: '固まった部分をカード、残った液体をホエー（乳清）という。' },
  { id: 'p24', f: 'food', q: 'チーズづくりで、カードと分かれて出てくる黄色みがかった液体は？', c: ['ホエー（乳清）', 'カード', 'バターミルク', '豆乳'], e: 'ホエーはたんぱく質やミネラルを含み、飲料などに利用される。' },
  { id: 'p25', f: 'food', q: 'クリームを激しくかくはんして脂肪球を集め、バター粒をつくる工程は？', c: ['チャーニング', 'ワーキング', 'ホモジナイズ', 'エージング'], e: 'バター粒を練り合わせて組織を整える工程をワーキングという。' },
  { id: 'p26', f: 'food', q: 'アイスクリームで、製造中に含ませた空気によって体積が増えた割合を何という？', c: ['オーバーラン', '歩留まり', '水分活性', '糖度'], e: 'オーバーランが大きいほど、軽くやわらかい食感になる。' },
  { id: 'p27', f: 'food', q: 'ハム・ソーセージづくりで、肉に食塩や発色剤などをすり込んで低温で漬け込む工程は？', c: ['塩せき', '燻煙', '充てん', '乳化'], e: '肉の保水性・結着性を高め、色と風味をよくする。' },
  { id: 'p28', f: 'food', q: 'ハムやソーセージの肉の赤い色を保つために使われる発色剤は？', c: ['亜硝酸ナトリウム', 'ソルビン酸', '塩化マグネシウム', 'クエン酸'], e: '肉の色素ミオグロビンと結びついて赤色を安定させる。ボツリヌス菌の増殖を抑える効果もある。' },
  { id: 'p29', f: 'food', q: 'ソーセージで、ひき肉を詰める袋状のものを何という？', c: ['ケーシング', 'ラップ', 'ネット', 'カード'], e: '羊や豚の腸の天然ケーシングと、コラーゲンなどの人工ケーシングがある。' },
  { id: 'p30', f: 'food', q: 'ジャムがゼリー状に固まる（ゲル化する）ために必要な3つの要素は？', c: ['ペクチン・酸・糖', 'でんぷん・塩・水', 'ゼラチン・油・砂糖', '寒天・塩・酢'], e: 'ペクチンは果実に含まれる多糖類で、リンゴや柑橘類に多い。' },
  { id: 'p31', f: 'food', q: 'ジャムの煮詰めの終わり（終点）を判断する方法として適切なものは？', c: ['糖度計で糖度を測る', '色だけで判断する', '時間だけで決める', 'においで判断する'], e: 'コップの水に1滴落としてすぐに散らなければ終点とする方法（コップテスト）もある。' },
  { id: 'p32', f: 'food', q: 'パンづくりで、生地をふくらませる微生物は？', c: ['酵母（イースト）', '乳酸菌', '麹菌', '納豆菌'], e: '酵母が糖を分解して二酸化炭素とアルコールをつくる。その気体がグルテンの膜に包まれて生地がふくらむ。' },
  { id: 'p33', f: 'food', q: '小麦粉に水を加えてこねたときにできる、粘りと弾力のあるたんぱく質は？', c: ['グルテン', 'カゼイン', 'ペクチン', 'アミロース'], e: 'グリアジンとグルテニンが結びついてできる。' },
  { id: 'p34', f: 'food', q: 'パンづくりで、分割・丸めした生地を休ませる時間を何という？', c: ['ベンチタイム', '一次発酵', '焼成', 'ホイロ'], e: '生地の緊張をゆるめて成形しやすくする。成形後の最終発酵をホイロという。' },
  { id: 'p35', f: 'food', q: '豆腐づくりで、豆乳を固めるのに使う「にがり」の主成分は？', c: ['塩化マグネシウム', '塩化ナトリウム', '炭酸カルシウム', 'クエン酸'], e: '硫酸カルシウム（すまし粉）なども凝固剤として使われる。' },
  { id: 'p36', f: 'food', q: '豆腐づくりで、豆乳をしぼったあとに残るものは？', c: ['おから', 'ゆば', 'ホエー', 'ふすま'], e: 'おからは食物繊維が豊富。ゆばは豆乳を加熱したときにできる表面の膜。' },
  { id: 'p37', f: 'food', q: 'みその主な原料は？', c: ['大豆・こうじ・食塩', '大豆・にがり・水', '小麦・酵母・食塩', '米・酢・砂糖'], e: '米こうじを使う米みそ、麦こうじの麦みそ、大豆こうじの豆みそがある。' },
  { id: 'p38', f: 'food', q: 'みそ・しょうゆ・日本酒づくりに使われ、日本の「国菌」とされるカビは？', c: ['ニホンコウジカビ（麹菌）', 'アオカビ', 'クロカビ', 'ケカビ'], e: 'でんぷんを糖に、たんぱく質をアミノ酸に分解する酵素をつくる。' },
  { id: 'p39', f: 'food', q: '納豆のネバネバ（糸）の主な成分は？', c: ['ポリグルタミン酸', 'ペクチン', 'グルテン', 'カゼイン'], e: '納豆菌がつくる成分で、ポリグルタミン酸とフラクタンからなる。' },
  { id: 'p40', f: 'food', q: 'アルコールを酢酸に変える微生物は？', c: ['酢酸菌', '乳酸菌', '酵母', '麹菌'], e: '食酢は、原料の糖を酵母でアルコール発酵させたあと、酢酸菌で酢酸発酵させてつくる。' },
  { id: 'p41', f: 'food', q: 'こんにゃくいもからこんにゃくをつくるとき、固めるために使うものは？', c: ['水酸化カルシウム（消石灰）', 'にがり', 'ゼラチン', '寒天'], e: 'こんにゃくいものグルコマンナンが、アルカリによって固まる。' },
  { id: 'p42', f: 'food', q: 'トマトを裏ごしして煮詰めた、ケチャップなどの原料になる加工品は？', c: ['トマトピューレー', 'トマトジュース', 'ホールトマト', 'ドライトマト'], e: 'さらに濃縮したものをトマトペーストという。' },
  { id: 'p43', f: 'food', q: '食品の加工で、原料の量に対する製品の量の割合を何という？', c: ['歩留まり', '水分活性', '糖度', '収量構成'], e: '歩留まりを上げることは、原価を下げることにつながる。' },
  { id: 'p44', f: 'food', q: '原料の受け入れから出荷までの工程ごとに危害を分析し、重要な管理点を監視する食品衛生管理の手法は？', c: ['HACCP', 'GAP', 'IPM', 'JAS'], e: '2021年6月から、原則としてすべての食品等事業者にHACCPに沿った衛生管理が義務づけられた。' },
  { id: 'p45', f: 'food', q: '食品表示で、「安全に食べられる期限」を示すものは？', c: ['消費期限', '賞味期限', '製造年月日', '販売期限'], e: '消費期限は弁当など傷みやすい食品に、賞味期限はおいしく食べられる期限で比較的長持ちする食品に表示される。' },
  { id: 'p46', f: 'food', q: 'アレルギー表示が義務づけられている「特定原材料」に含まれるものは？', c: ['そば', '大豆', 'りんご', 'バナナ'], e: '特定原材料（表示義務）には、えび・かに・くるみ・小麦・そば・卵・乳・落花生などがある（品目は見直されることがあるので最新の情報を確認）。大豆やりんご・バナナは表示が推奨される品目。' },
  { id: 'p47', f: 'food', q: 'つくる毒素が熱に強く、手指の傷などから食品に付着する食中毒菌は？', c: ['黄色ブドウ球菌', 'サルモネラ菌', '腸炎ビブリオ', 'カンピロバクター'], e: '毒素（エンテロトキシン）は加熱しても壊れにくい。手洗いと、手に傷があるときは手袋を使うことが大切。' },
  { id: 'p48', f: 'food', q: '鶏肉の生食や加熱不足で起こりやすい食中毒の原因菌は？', c: ['カンピロバクター', '腸炎ビブリオ', 'ボツリヌス菌', '黄色ブドウ球菌'], e: '少ない菌数でも発症する。中心部まで十分に加熱する（75℃で1分以上が目安）。' },
  { id: 'p49', f: 'food', q: '海水中にすみ、生の魚介類から感染することが多い食中毒菌は？', c: ['腸炎ビブリオ', 'カンピロバクター', 'ウェルシュ菌', 'セレウス菌'], e: '真水や加熱に弱い。魚介類は真水でよく洗い、低温で保存する。' },
  { id: 'p50', f: 'food', q: '冬に多く、二枚貝や人の手を介して広がる、ウイルスによる食中毒は？', c: ['ノロウイルス', 'サルモネラ菌', 'ボツリヌス菌', '黄色ブドウ球菌'], e: 'アルコールが効きにくいため、石けんでの手洗いと次亜塩素酸ナトリウムでの消毒が有効。' },
  { id: 'p51', f: 'food', q: 'ソルビン酸などのように、微生物の増殖を抑えて保存性を高める食品添加物は？', c: ['保存料', '酸化防止剤', '着色料', '甘味料'], e: '食品添加物は、使用できる物質と量が食品衛生法で定められている。' },
  { id: 'p52', f: 'food', q: '農業者が生産だけでなく、加工・販売まで一体的に取り組むことを何という？', c: ['6次産業化', '地産地消', '産地直送', '契約栽培'], e: '1次（生産）×2次（加工）×3次（販売）で「6次」。農業高校の加工品販売もその実践の一つ。' },
];
